// Generated by scripts/fetch_verses.py — 和合本 (CUV, public domain) + World English Bible (public domain)
window.BIBLE_TEXT = window.BIBLE_TEXT || {};
window.BIBLE_TEXT["daniel"] = {
 "1": {
  "1": {
   "zh": "猶大王約雅敬在位第三年，巴比倫王尼布甲尼撒來到耶路撒冷，將城圍困。",
   "en": "In the third year of the reign of Jehoiakim king of Judah Nebuchadnezzar king of Babylon came to Jerusalem and besieged it."
  },
  "2": {
   "zh": "主將猶大王約雅敬，並神殿中器皿的幾分交付他手。他就把這器皿帶到示拿地，收入他神的廟裡，放在他神的庫中。",
   "en": "The Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God; and he carried them into the land of Shinar to the house of his god. He brought the vessels into the treasure house of his god."
  },
  "3": {
   "zh": "王吩咐太監長亞施毘拿，從以色列人的宗室和貴冑中帶進幾個人來，",
   "en": "The king spoke to Ashpenaz the master of his eunuchs, that he should bring in some of the children of Israel, even of the royal offspring and of the nobles;"
  },
  "4": {
   "zh": "就是年少沒有殘疾、相貌俊美、通達各樣學問、知識聰明俱備、足能侍立在王宮裡的，要教他們迦勒底的文字言語。",
   "en": "youths in whom was no defect, but well-favored, and skillful in all wisdom, and endowed with knowledge, and understanding science, and who had the ability to stand in the king’s palace; and that he should teach them the learning and the language of the Chaldeans."
  },
  "5": {
   "zh": "王派定將自己所用的膳和所飲的酒，每日賜他們一分，養他們三年。滿了三年，好叫他們在王面前侍立。",
   "en": "The king appointed for them a daily portion of the king’s dainties, and of the wine which he drank, and that they should be nourished three years; that at its end they should stand before the king."
  },
  "6": {
   "zh": "他們中間有猶大族的人：但以理、哈拿尼雅、米沙利、亞撒利雅。",
   "en": "Now among these were of the children of Judah: Daniel, Hananiah, Mishael, and Azariah."
  },
  "7": {
   "zh": "太監長給他們起名：稱但以理為伯提沙撒，稱哈拿尼雅為沙得拉，稱米沙利為米煞，稱亞撒利雅為亞伯尼歌。",
   "en": "The prince of the eunuchs gave names to them: to Daniel he gave the name Belteshazzar; to Hananiah, Shadrach; to Mishael, Meshach; and to Azariah, Abednego."
  },
  "8": {
   "zh": "但以理卻立志不以王的膳和王所飲的酒玷污自己，所以求太監長容他不玷污自己。",
   "en": "But Daniel purposed in his heart that he would not defile himself with the king’s dainties, nor with the wine which he drank. Therefore he requested of the prince of the eunuchs that he might not defile himself."
  },
  "9": {
   "zh": "神使但以理在太監長眼前蒙恩惠，受憐憫。",
   "en": "Now God made Daniel find kindness and compassion in the sight of the prince of the eunuchs."
  },
  "10": {
   "zh": "太監長對但以理說：「我懼怕我主我王，他已經派定你們的飲食；倘若他見你們的面貌比你們同歲的少年人肌瘦，怎麼好呢？這樣，你們就使我的頭在王那裡難保。」",
   "en": "The prince of the eunuchs said to Daniel, “I fear my lord the king, who has appointed your food and your drink. For why should he see your faces worse looking than the youths who are of your own age? So would you endanger my head with the king.”"
  },
  "11": {
   "zh": "但以理對太監長所派管理但以理、哈拿尼雅、米沙利、亞撒利雅的委辦說：",
   "en": "Then Daniel said to the steward whom the prince of the eunuchs had appointed over Daniel, Hananiah, Mishael, and Azariah:"
  },
  "12": {
   "zh": "「求你試試僕人們十天，給我們素菜吃，白水喝，",
   "en": "“Test your servants, I beg you, ten days; and let them give us vegetables to eat, and water to drink."
  },
  "13": {
   "zh": "然後看看我們的面貌和用王膳那少年人的面貌，就照你所看的待僕人吧！」",
   "en": "Then let our faces be examined before you, and the face of the youths who eat of the king’s dainties; and as you see, deal with your servants.”"
  },
  "14": {
   "zh": "委辦便允准他們這件事，試看他們十天。",
   "en": "So he listened to them in this matter, and tested them for ten days."
  },
  "15": {
   "zh": "過了十天，見他們的面貌比用王膳的一切少年人更加俊美肥胖。",
   "en": "At the end of ten days, their faces appeared fairer, and they were fatter in flesh, than all the youths who ate of the king’s dainties."
  },
  "16": {
   "zh": "於是委辦撤去派他們用的膳，飲的酒，給他們素菜吃。",
   "en": "So the steward took away their dainties, and the wine that they would drink, and gave them vegetables."
  },
  "17": {
   "zh": "這四個少年人，神在各樣文字學問（學問：原文是智慧）上賜給他們聰明知識；但以理又明白各樣的異象和夢兆。",
   "en": "Now as for these four youths, God gave them knowledge and skill in all learning and wisdom; and Daniel had understanding in all visions and dreams."
  },
  "18": {
   "zh": "尼布甲尼撒王預定帶進少年人來的日期滿了，太監長就把他們帶到王面前。",
   "en": "At the end of the days which the king had appointed for bringing them in, the prince of the eunuchs brought them in before Nebuchadnezzar."
  },
  "19": {
   "zh": "王與他們談論，見少年人中無一人能比但以理、哈拿尼雅、米沙利、亞撒利雅，所以留他們在王面前侍立。",
   "en": "The king talked with them; and among them all was found no one like Daniel, Hananiah, Mishael, and Azariah. Therefore stood they before the king."
  },
  "20": {
   "zh": "王考問他們一切事，就見他們的智慧聰明比通國的術士和用法術的勝過十倍。",
   "en": "In every matter of wisdom and understanding, concerning which the king inquired of them, he found them ten times better than all the magicians and enchanters who were in all his realm."
  },
  "21": {
   "zh": "到古列王元年，但以理還在。",
   "en": "Daniel continued even to the first year of king Cyrus."
  }
 },
 "2": {
  "1": {
   "zh": "尼布甲尼撒在位第二年，他做了夢，心裡煩亂，不能睡覺。",
   "en": "In the second year of the reign of Nebuchadnezzar, Nebuchadnezzar dreamed dreams; and his spirit was troubled, and his sleep went from him."
  },
  "2": {
   "zh": "王吩咐人將術士、用法術的、行邪術的，和迦勒底人召來，要他們將王的夢告訴王，他們就來站在王前。",
   "en": "Then the king commanded to call the magicians, and the enchanters, and the sorcerers, and the Chaldeans, to tell the king his dreams. So they came in and stood before the king."
  },
  "3": {
   "zh": "王對他們說：「我做了一夢，心裡煩亂，要知道這是甚麼夢。」",
   "en": "The king said to them, “I have dreamed a dream, and my spirit is troubled to know the dream.”"
  },
  "4": {
   "zh": "迦勒底人用亞蘭的言語對王說：「願王萬歲！請將那夢告訴僕人，僕人就可以講解。」",
   "en": "Then the Chaldeans spoke to the king in the Syrian language, “O king, live forever! Tell your servants the dream, and we will show the interpretation.”"
  },
  "5": {
   "zh": "王回答迦勒底人說：「夢我已經忘了（或譯：我已定命；八節同），你們若不將夢和夢的講解告訴我，就必被凌遲，你們的房屋必成為糞堆；",
   "en": "The king answered the Chaldeans, “The thing has gone from me. If you don’t make known to me the dream and its interpretation, you will be cut in pieces, and your houses will be made a dunghill."
  },
  "6": {
   "zh": "你們若將夢和夢的講解告訴我，就必從我這裡得贈品和賞賜，並大尊榮。現在你們要將夢和夢的講解告訴我。」",
   "en": "But if you show the dream and its interpretation, you will receive of me gifts and rewards and great honor. Therefore show me the dream and its interpretation.”"
  },
  "7": {
   "zh": "他們第二次對王說：「請王將夢告訴僕人，僕人就可以講解。」",
   "en": "They answered the second time and said, “Let the king tell his servants the dream, and we will show the interpretation.”"
  },
  "8": {
   "zh": "王回答說：「我准知道你們是故意遲延，因為你們知道那夢我已經忘了。",
   "en": "The king answered, “I know of a certainty that you are trying to gain time, because you see the thing has gone from me."
  },
  "9": {
   "zh": "你們若不將夢告訴我，只有一法待你們；因為你們預備了謊言亂語向我說，要等候時勢改變。現在你們要將夢告訴我，因我知道你們能將夢的講解告訴我。」",
   "en": "But if you don’t make known to me the dream, there is but one law for you; for you have prepared lying and corrupt words to speak before me, until the situation changes. Therefore tell me the dream, and I will know that you can show me its interpretation.”"
  },
  "10": {
   "zh": "迦勒底人在王面前回答說：「世上沒有人能將王所問的事說出來；因為沒有君王、大臣、掌權的向術士，或用法術的，或迦勒底人問過這樣的事。",
   "en": "The Chaldeans answered before the king, and said, “There is not a man on the earth who can show the king’s matter, because no king, lord, or ruler, has asked such a thing of any magician, or enchanter, or Chaldean."
  },
  "11": {
   "zh": "王所問的事甚難。除了不與世人同居的神明，沒有人在王面前能說出來。」",
   "en": "It is a rare thing that the king requires, and there is no other who can show it before the king, except the gods, whose dwelling is not with flesh.”"
  },
  "12": {
   "zh": "因此，王氣忿忿地大發烈怒，吩咐滅絕巴比倫所有的哲士。",
   "en": "Because of this, the king was angry and very furious, and commanded that all the wise men of Babylon be destroyed."
  },
  "13": {
   "zh": "於是命令發出，哲士將要見殺，人就尋找但以理和他的同伴，要殺他們。",
   "en": "So the decree went out, and the wise men were to be slain. They sought Daniel and his companions to be slain."
  },
  "14": {
   "zh": "王的護衛長亞略出來，要殺巴比倫的哲士，但以理就用婉言回答他，",
   "en": "Then Daniel returned answer with counsel and prudence to Arioch the captain of the king’s guard, who had gone out to kill the wise men of Babylon."
  },
  "15": {
   "zh": "向王的護衛長亞略說：「王的命令為何這樣緊急呢？」亞略就將情節告訴但以理。",
   "en": "He answered Arioch the king’s captain, “Why is the decree so urgent from the king?” Then Arioch made the thing known to Daniel."
  },
  "16": {
   "zh": "但以理遂進去求王寬限，就可以將夢的講解告訴王。",
   "en": "Daniel went in, and desired of the king that he would appoint him a time, and he would show the king the interpretation."
  },
  "17": {
   "zh": "但以理回到他的居所，將這事告訴他的同伴哈拿尼雅、米沙利、亞撒利雅，",
   "en": "Then Daniel went to his house and made the thing known to Hananiah, Mishael, and Azariah, his companions:"
  },
  "18": {
   "zh": "要他們祈求天上的神施憐憫，將這奧祕的事指明，免得但以理和他的同伴與巴比倫其餘的哲士一同滅亡。",
   "en": "that they would desire mercies of the God of heaven concerning this secret; that Daniel and his companions would not perish with the rest of the wise men of Babylon."
  },
  "19": {
   "zh": "這奧祕的事就在夜間異象中給但以理顯明，但以理便稱頌天上的神。",
   "en": "Then the secret was revealed to Daniel in a vision of the night. Then Daniel blessed the God of heaven."
  },
  "20": {
   "zh": "但以理說：「神的名是應當稱頌的！從亙古直到永遠，因為智慧能力都屬乎他。",
   "en": "Daniel answered, “Blessed be the name of God forever and ever; for wisdom and might are his."
  },
  "21": {
   "zh": "他改變時候、日期，廢王，立王，將智慧賜與智慧人，將知識賜與聰明人。",
   "en": "He changes the times and the seasons. He removes kings, and sets up kings. He gives wisdom to the wise, and knowledge to those who have understanding."
  },
  "22": {
   "zh": "他顯明深奧隱祕的事，知道暗中所有的，光明也與他同居。",
   "en": "He reveals the deep and secret things. He knows what is in the darkness, and the light dwells with him."
  },
  "23": {
   "zh": "我列祖的神啊，我感謝你，讚美你，因你將智慧才能賜給我，允准我們所求的，把王的事給我們指明。」",
   "en": "I thank you, and praise you, you God of my fathers, who have given me wisdom and might, and have now made known to me what we desired of you; for you have made known to us the king’s matter.”"
  },
  "24": {
   "zh": "於是，但以理進去見亞略，就是王所派滅絕巴比倫哲士的，對他說：「不要滅絕巴比倫的哲士，求你領我到王面前，我要將夢的講解告訴王。」",
   "en": "Therefore Daniel went in to Arioch, whom the king had appointed to destroy the wise men of Babylon. He went and said this to him: “Don’t destroy the wise men of Babylon. Bring me in before the king, and I will show to the king the interpretation.”"
  },
  "25": {
   "zh": "亞略就急忙將但以理領到王面前，對王說：「我在被擄的猶大人中遇見一人，他能將夢的講解告訴王。」",
   "en": "Then Arioch brought in Daniel before the king in haste, and said this to him: “I have found a man of the children of the captivity of Judah who will make known to the king the interpretation.”"
  },
  "26": {
   "zh": "王問稱為伯提沙撒的但以理說：「你能將我所做的夢和夢的講解告訴我嗎？」",
   "en": "The king answered Daniel, whose name was Belteshazzar, “Are you able to make known to me the dream which I have seen, and its interpretation?”"
  },
  "27": {
   "zh": "但以理在王面前回答說：「王所問的那奧祕事，哲士、用法術的、術士、觀兆的都不能告訴王；",
   "en": "Daniel answered before the king, and said, “The secret which the king has demanded can’t be shown to the king by wise men, enchanters, magicians, or soothsayers;"
  },
  "28": {
   "zh": "只有一位在天上的神能顯明奧祕的事。他已將日後必有的事指示尼布甲尼撒王。你的夢和你在床上腦中的異象是這樣：",
   "en": "but there is a God in heaven who reveals secrets, and he has made known to the king Nebuchadnezzar what will be in the latter days. Your dream, and the visions of your head on your bed, are these:"
  },
  "29": {
   "zh": "王啊，你在床上想到後來的事，那顯明奧祕事的主把將來必有的事指示你。",
   "en": "“As for you, O king, your thoughts came on your bed, what should happen hereafter; and he who reveals secrets has made known to you what will happen."
  },
  "30": {
   "zh": "至於那奧祕的事顯明給我，並非因我的智慧勝過一切活人，乃為使王知道夢的講解和心裡的思念。",
   "en": "But as for me, this secret is not revealed to me for any wisdom that I have more than any living, but to the intent that the interpretation may be made known to the king, and that you may know the thoughts of your heart."
  },
  "31": {
   "zh": "「王啊，你夢見一個大像，這像甚高，極其光耀，站在你面前，形狀甚是可怕。",
   "en": "“You, O king, saw, and behold, a great image. This image, which was mighty, and whose brightness was excellent, stood before you; and its appearance was terrifying."
  },
  "32": {
   "zh": "這像的頭是精金的，胸膛和膀臂是銀的，肚腹和腰是銅的，",
   "en": "As for this image, its head was of fine gold, its breast and its arms of silver, its belly and its thighs of brass,"
  },
  "33": {
   "zh": "腿是鐵的，腳是半鐵半泥的。",
   "en": "its legs of iron, its feet part of iron, and part of clay."
  },
  "34": {
   "zh": "你觀看，見有一塊非人手鑿出來的石頭打在這像半鐵半泥的腳上，把腳砸碎；",
   "en": "You saw until a stone was cut out without hands, which struck the image on its feet that were of iron and clay, and broke them in pieces."
  },
  "35": {
   "zh": "於是金、銀、銅、鐵、泥都一同砸得粉碎，成如夏天禾場上的糠秕，被風吹散，無處可尋。打碎這像的石頭變成一座大山，充滿天下。",
   "en": "Then the iron, the clay, the brass, the silver, and the gold were broken in pieces together, and became like the chaff of the summer threshing floors. The wind carried them away, so that no place was found for them. The stone that struck the image became a great mountain, and filled the whole earth."
  },
  "36": {
   "zh": "「這就是那夢。我們在王面前要講解那夢。",
   "en": "“This is the dream; and we will tell its interpretation before the king."
  },
  "37": {
   "zh": "王啊，你是諸王之王。天上的神已將國度、權柄、能力、尊榮都賜給你。",
   "en": "You, O king, are king of kings, to whom the God of heaven has given the kingdom, the power, the strength, and the glory."
  },
  "38": {
   "zh": "凡世人所住之地的走獸，並天空的飛鳥，他都交付你手，使你掌管這一切。你就是那金頭。",
   "en": "Wherever the children of men dwell, he has given the animals of the field and the birds of the sky into your hand, and has made you rule over them all. You are the head of gold."
  },
  "39": {
   "zh": "在你以後必另興一國，不及於你；又有第三國，就是銅的，必掌管天下。",
   "en": "“After you, another kingdom will arise that is inferior to you; and another third kingdom of brass, which will rule over all the earth."
  },
  "40": {
   "zh": "第四國，必堅壯如鐵，鐵能打碎剋制百物，又能壓碎一切，那國也必打碎壓制列國。",
   "en": "The fourth kingdom will be strong as iron, because iron breaks in pieces and subdues all things; and as iron that crushes all these, it will break in pieces and crush."
  },
  "41": {
   "zh": "你既見像的腳和腳指頭，一半是窯匠的泥，一半是鐵，那國將來也必分開。你既見鐵與泥攙雜，那國也必有鐵的力量。",
   "en": "Whereas you saw the feet and toes, part of potters’ clay, and part of iron, it will be a divided kingdom; but there will be in it of the strength of the iron, because you saw the iron mixed with miry clay."
  },
  "42": {
   "zh": "那腳指頭，既是半鐵半泥，那國也必半強半弱。",
   "en": "As the toes of the feet were part of iron, and part of clay, so the kingdom will be partly strong, and partly broken."
  },
  "43": {
   "zh": "你既見鐵與泥攙雜，那國民也必與各種人攙雜，卻不能彼此相合，正如鐵與泥不能相合一樣。",
   "en": "Whereas you saw the iron mixed with miry clay, they will mingle themselves with the seed of men; but they won’t cling to one another, even as iron does not mix with clay."
  },
  "44": {
   "zh": "當那列王在位的時候，天上的神必另立一國，永不敗壞，也不歸別國的人，卻要打碎滅絕那一切國，這國必存到永遠。",
   "en": "“In the days of those kings the God of heaven will set up a kingdom which will never be destroyed, nor will its sovereignty be left to another people; but it will break in pieces and consume all these kingdoms, and it will stand forever."
  },
  "45": {
   "zh": "你既看見非人手鑿出來的一塊石頭從山而出，打碎金、銀、銅、鐵、泥，那就是至大的神把後來必有的事給王指明。這夢準是這樣，這講解也是確實的。」",
   "en": "Because you saw that a stone was cut out of the mountain without hands, and that it broke in pieces the iron, the brass, the clay, the silver, and the gold; the great God has made known to the king what will happen hereafter. The dream is certain, and its interpretation sure.”"
  },
  "46": {
   "zh": "當時，尼布甲尼撒王俯伏在地，向但以理下拜，並且吩咐人給他奉上供物和香品。",
   "en": "Then the king Nebuchadnezzar fell on his face, worshiped Daniel, and commanded that they should offer an offering and sweet odors to him."
  },
  "47": {
   "zh": "王對但以理說：「你既能顯明這奧祕的事，你們的神誠然是萬神之神、萬王之主，又是顯明奧祕事的。」",
   "en": "The king answered to Daniel, and said, “Of a truth your God is the God of gods, and the Lord of kings, and a revealer of secrets, since you have been able to reveal this secret.”"
  },
  "48": {
   "zh": "於是王高抬但以理，賞賜他許多上等禮物，派他管理巴比倫全省，又立他為總理，掌管巴比倫的一切哲士。",
   "en": "Then the king made Daniel great, and gave him many great gifts, and made him rule over the whole province of Babylon, and to be chief governor over all the wise men of Babylon."
  },
  "49": {
   "zh": "但以理求王，王就派沙得拉、米煞、亞伯尼歌管理巴比倫省的事務，只是但以理常在朝中侍立。",
   "en": "Daniel requested of the king, and he appointed Shadrach, Meshach, and Abednego over the affairs of the province of Babylon; but Daniel was in the king’s gate."
  }
 },
 "3": {
  "1": {
   "zh": "尼布甲尼撒王造了一個金像，高六十肘，寬六肘，立在巴比倫省杜拉平原。",
   "en": "Nebuchadnezzar the king made an image of gold, whose height was sixty cubits, and its width six cubits. He set it up in the plain of Dura, in the province of Babylon."
  },
  "2": {
   "zh": "尼布甲尼撒王差人將總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都召了來，為尼布甲尼撒王所立的像行開光之禮。",
   "en": "Then Nebuchadnezzar the king sent to gather together the satraps, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces, to come to the dedication of the image which Nebuchadnezzar the king had set up."
  },
  "3": {
   "zh": "於是總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都聚集了來，要為尼布甲尼撒王所立的像行開光之禮，就站在尼布甲尼撒所立的像前。",
   "en": "Then the satraps, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces, were gathered together to the dedication of the image that Nebuchadnezzar the king had set up; and they stood before the image that Nebuchadnezzar had set up."
  },
  "4": {
   "zh": "那時傳令的大聲呼叫說：「各方、各國、各族（原文是舌：下同）的人哪，有令傳與你們：",
   "en": "Then the herald cried aloud, “To you it is commanded, peoples, nations, and languages,"
  },
  "5": {
   "zh": "你們一聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，就當俯伏敬拜尼布甲尼撒王所立的金像。",
   "en": "that whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, you fall down and worship the golden image that Nebuchadnezzar the king has set up."
  },
  "6": {
   "zh": "凡不俯伏敬拜的，必立時扔在烈火的窯中。」",
   "en": "Whoever doesn’t fall down and worship shall be cast into the middle of a burning fiery furnace the same hour.”"
  },
  "7": {
   "zh": "因此各方、各國、各族的人民一聽見角、笛、琵琶、琴、瑟，和各樣樂器的聲音，就都俯伏敬拜尼布甲尼撒王所立的金像。",
   "en": "Therefore at that time, when all the peoples heard the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, all the peoples, the nations, and the languages, fell down and worshiped the golden image that Nebuchadnezzar the king had set up."
  },
  "8": {
   "zh": "那時，有幾個迦勒底人進前來控告猶大人。",
   "en": "Therefore at that time certain Chaldeans came near, and brought accusation against the Jews."
  },
  "9": {
   "zh": "他們對尼布甲尼撒王說：「願王萬歲！",
   "en": "They answered Nebuchadnezzar the king, “O king, live for ever!"
  },
  "10": {
   "zh": "王啊，你曾降旨說，凡聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器聲音的都當俯伏敬拜金像。",
   "en": "You, O king, have made a decree, that every man that hears the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, shall fall down and worship the golden image;"
  },
  "11": {
   "zh": "凡不俯伏敬拜的，必扔在烈火的窯中。",
   "en": "and whoever doesn’t fall down and worship shall be cast into the middle of a burning fiery furnace."
  },
  "12": {
   "zh": "現在有幾個猶大人，就是王所派管理巴比倫省事務的沙得拉、米煞、亞伯尼歌；王啊，這些人不理你，不事奉你的神，也不敬拜你所立的金像。」",
   "en": "There are certain Jews whom you have appointed over the affairs of the province of Babylon: Shadrach, Meshach, and Abednego. These men, O king, have not respected you. They don’t serve your gods, and don’t worship the golden image which you have set up.”"
  },
  "13": {
   "zh": "當時，尼布甲尼撒沖沖大怒，吩咐人把沙得拉、米煞、亞伯尼歌帶過來，他們就把那些人帶到王面前。",
   "en": "Then Nebuchadnezzar in rage and fury commanded that Shadrach, Meshach, and Abednego be brought. Then these men were brought before the king."
  },
  "14": {
   "zh": "尼布甲尼撒問他們說：「沙得拉、米煞、亞伯尼歌，你們不事奉我的神，也不敬拜我所立的金像，是故意的嗎？",
   "en": "Nebuchadnezzar answered them, “Is it on purpose, Shadrach, Meshach, and Abednego, that you don’t serve my god, nor worship the golden image which I have set up?"
  },
  "15": {
   "zh": "你們再聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，若俯伏敬拜我所造的像，卻還可以；若不敬拜，必立時扔在烈火的窯中，有何神能救你們脫離我手呢？」",
   "en": "Now if you are ready whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music to fall down and worship the image which I have made, good; but if you don’t worship, you shall be cast the same hour into the middle of a burning fiery furnace. Who is that god that will deliver you out of my hands?”"
  },
  "16": {
   "zh": "沙得拉、米煞、亞伯尼歌對王說：「尼布甲尼撒啊，這件事我們不必回答你；",
   "en": "Shadrach, Meshach, and Abednego answered the king, “Nebuchadnezzar, we have no need to answer you in this matter."
  },
  "17": {
   "zh": "即便如此，我們所事奉的神能將我們從烈火的窯中救出來。王啊，他也必救我們脫離你的手；",
   "en": "If it happens, our God whom we serve is able to deliver us from the burning fiery furnace; and he will deliver us out of your hand, O king."
  },
  "18": {
   "zh": "即或不然，王啊，你當知道我們決不事奉你的神，也不敬拜你所立的金像。」",
   "en": "But if not, let it be known to you, O king, that we will not serve your gods or worship the golden image which you have set up.”"
  },
  "19": {
   "zh": "當時，尼布甲尼撒怒氣填胸，向沙得拉、米煞、亞伯尼歌變了臉色，吩咐人把窯燒熱，比尋常更加七倍；",
   "en": "Then Nebuchadnezzar was full of fury, and the form of his appearance was changed against Shadrach, Meshach, and Abednego. He spoke, and commanded that they should heat the furnace seven times more than it was usually heated."
  },
  "20": {
   "zh": "又吩咐他軍中的幾個壯士，將沙得拉、米煞、亞伯尼歌捆起來，扔在烈火的窯中。",
   "en": "He commanded certain mighty men who were in his army to bind Shadrach, Meshach, and Abednego, and to cast them into the burning fiery furnace."
  },
  "21": {
   "zh": "這三人穿著褲子、內袍、外衣，和別的衣服，被捆起來扔在烈火的窯中。",
   "en": "Then these men were bound in their pants, their tunics, and their mantles, and their other clothes, and were cast into the middle of the burning fiery furnace."
  },
  "22": {
   "zh": "因為王命緊急，窯又甚熱，那抬沙得拉、米煞、亞伯尼歌的人都被火焰燒死。",
   "en": "Therefore because the king’s commandment was urgent, and the furnace exceeding hot, the flame of the fire killed those men who took up Shadrach, Meshach, and Abednego."
  },
  "23": {
   "zh": "沙得拉、米煞、亞伯尼歌這三個人都被捆著落在烈火的窯中。",
   "en": "These three men, Shadrach, Meshach, and Abednego, fell down bound into the middle of the burning fiery furnace."
  },
  "24": {
   "zh": "那時，尼布甲尼撒王驚奇，急忙起來，對謀士說：「我捆起來扔在火裡的不是三個人嗎？」他們回答王說：「王啊，是。」",
   "en": "Then Nebuchadnezzar the king was astonished, and rose up in haste. He spoke and said to his counselors, “Didn’t we cast three men bound into the middle of the fire?” They answered the king, “True, O king.”"
  },
  "25": {
   "zh": "王說：「看哪，我見有四個人，並沒有捆綁，在火中遊行，也沒有受傷；那第四個的相貌好像神子。」",
   "en": "He answered, “Look, I see four men loose, walking in the middle of the fire, and they are unharmed. The appearance of the fourth is like a son of the gods.”"
  },
  "26": {
   "zh": "於是，尼布甲尼撒就近烈火窯門，說：「至高神的僕人沙得拉、米煞、亞伯尼歌出來，上這裡來吧！」沙得拉、米煞、亞伯尼歌就從火中出來了。",
   "en": "Then Nebuchadnezzar came near to the mouth of the burning fiery furnace. He spoke and said, “Shadrach, Meshach, and Abednego, you servants of the Most High God, come out, and come here!” Then Shadrach, Meshach, and Abednego came out of the middle of the fire."
  },
  "27": {
   "zh": "那些總督、欽差、巡撫，和王的謀士一同聚集看這三個人，見火無力傷他們的身體，頭髮也沒有燒焦，衣裳也沒有變色，並沒有火燎的氣味。",
   "en": "The satraps, the deputies, and the governors, and the king’s counselors, being gathered together, saw these men, that the fire had no power on their bodies. The hair of their head wasn’t singed. Their pants weren’t changed, the smell of fire wasn’t even on them."
  },
  "28": {
   "zh": "尼布甲尼撒說：「沙得拉、米煞、亞伯尼歌的神是應當稱頌的！他差遣使者救護倚靠他的僕人，他們不遵王命，捨去己身，在他們神以外不肯事奉敬拜別神。",
   "en": "Nebuchadnezzar spoke and said, “Blessed be the God of Shadrach, Meshach, and Abednego, who has sent his angel, and delivered his servants who trusted in him, and have changed the king’s word, and have yielded their bodies, that they might not serve nor worship any god, except their own God."
  },
  "29": {
   "zh": "現在我降旨，無論何方、何國、何族的人，謗讟沙得拉、米煞、亞伯尼歌之神的，必被凌遲，他的房屋必成糞堆，因為沒有別神能這樣施行拯救。」",
   "en": "Therefore I make a decree, that every people, nation, and language, which speak anything evil against the God of Shadrach, Meshach, and Abednego, shall be cut in pieces, and their houses shall be made a dunghill; because there is no other god who is able to deliver like this.”"
  },
  "30": {
   "zh": "那時王在巴比倫省，高升了沙得拉、米煞、亞伯尼歌。",
   "en": "Then the king promoted Shadrach, Meshach, and Abednego in the province of Babylon."
  }
 },
 "4": {
  "1": {
   "zh": "尼布甲尼撒王曉諭住在全地各方、各國、各族的人說：「願你們大享平安！",
   "en": "Nebuchadnezzar the king, to all the peoples, nations, and languages, who dwell in all the earth: Peace be multiplied to you."
  },
  "2": {
   "zh": "我樂意將至高的神向我所行的神蹟奇事宣揚出來。",
   "en": "It has seemed good to me to show the signs and wonders that the Most High God has worked toward me."
  },
  "3": {
   "zh": "他的神蹟何其大！他的奇事何其盛！他的國是永遠的；他的權柄存到萬代！",
   "en": "How great are his signs! How mighty are his wonders! His kingdom is an everlasting kingdom. His dominion is from generation to generation."
  },
  "4": {
   "zh": "「我尼布甲尼撒安居在宮中，平順在殿內。",
   "en": "I, Nebuchadnezzar, was at rest in my house, and flourishing in my palace."
  },
  "5": {
   "zh": "我做了一夢，使我懼怕。我在床上的思念，並腦中的異象，使我驚惶。",
   "en": "I saw a dream which made me afraid; and the thoughts on my bed and the visions of my head troubled me."
  },
  "6": {
   "zh": "所以我降旨召巴比倫的一切哲士到我面前，叫他們把夢的講解告訴我。",
   "en": "Therefore made I a decree to bring in all the wise men of Babylon before me, that they might make known to me the interpretation of the dream."
  },
  "7": {
   "zh": "於是那些術士、用法術的、迦勒底人、觀兆的都進來，我將那夢告訴了他們，他們卻不能把夢的講解告訴我。",
   "en": "Then the magicians, the enchanters, the Chaldeans, and the soothsayers came in; and I told the dream before them; but they did not make known to me its interpretation."
  },
  "8": {
   "zh": "末後那照我神的名，稱為伯提沙撒的但以理來到我面前，他裡頭有聖神的靈，我將夢告訴他說：",
   "en": "But at the last Daniel came in before me, whose name was Belteshazzar, according to the name of my god, and in whom is the spirit of the holy gods. I told the dream before him, saying,"
  },
  "9": {
   "zh": "『術士的領袖伯提沙撒啊，因我知道你裡頭有聖神的靈，甚麼奧祕的事都不能使你為難。現在要把我夢中所見的異象和夢的講解告訴我。』",
   "en": "“Belteshazzar, master of the magicians, because I know that the spirit of the holy gods is in you, and no secret troubles you, tell me the visions of my dream that I have seen, and its interpretation."
  },
  "10": {
   "zh": "「我在床上腦中的異象是這樣：我看見地當中有一棵樹，極其高大。",
   "en": "Thus were the visions of my head on my bed: I saw, and behold, a tree in the middle of the earth; and its height was great."
  },
  "11": {
   "zh": "那樹漸長，而且堅固，高得頂天，從地極都能看見，",
   "en": "The tree grew, and was strong, and its height reached to the sky, and its sight to the end of all the earth."
  },
  "12": {
   "zh": "葉子華美，果子甚多，可作眾生的食物；田野的走獸臥在蔭下，天空的飛鳥宿在枝上；凡有血氣的都從這樹得食。",
   "en": "The leaves of it were beautiful, and it had much fruit, and in it was food for all. The animals of the field had shade under it, and the birds of the sky lived in its branches, and all flesh was fed from it."
  },
  "13": {
   "zh": "「我在床上腦中的異象，見有一位守望的聖者從天而降。",
   "en": "“I saw in the visions of my head on my bed, and behold, a watcher and a holy one came down from the sky."
  },
  "14": {
   "zh": "大聲呼叫說：『伐倒這樹！砍下枝子！搖掉葉子！拋散果子！使走獸離開樹下，飛鳥躲開樹枝。",
   "en": "He cried aloud, and said thus, ‘Cut down the tree, and cut off its branches! Shake off its leaves, and scatter its fruit! Let the animals get away from under it, and the fowls from its branches."
  },
  "15": {
   "zh": "樹墩卻要留在地內，用鐵圈和銅圈箍住，在田野的青草中讓天露滴濕，使他與地上的獸一同吃草，",
   "en": "Nevertheless leave the stump of its roots in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of the sky. Let his portion be with the animals in the grass of the earth."
  },
  "16": {
   "zh": "使他的心改變，不如人心；給他一個獸心，使他經過七期（期：或譯年；本章同）。",
   "en": "Let his heart be changed from man’s, and let an animal’s heart be given to him. Then let seven times pass over him."
  },
  "17": {
   "zh": "這是守望者所發的命，聖者所出的令，好叫世人知道至高者在人的國中掌權，要將國賜與誰就賜與誰，或立極卑微的人執掌國權。』",
   "en": "“‘The sentence is by the decree of the watchers, and the demand by the word of the holy ones; to the intent that the living may know that the Most High rules in the kingdom of men, and gives it to whomever he will, and sets up over it the lowest of men.’"
  },
  "18": {
   "zh": "「這是我─尼布甲尼撒王所做的夢。伯提沙撒啊，你要說明這夢的講解；因為我國中的一切哲士都不能將夢的講解告訴我，惟獨你能，因你裡頭有聖神的靈。」",
   "en": "“This dream I, king Nebuchadnezzar, have seen; and you, Belteshazzar, declare the interpretation, because all the wise men of my kingdom are not able to make known to me the interpretation; but you are able; for the spirit of the holy gods is in you.”"
  },
  "19": {
   "zh": "於是稱為伯提沙撒的但以理驚訝片時，心意驚惶。王說：「伯提沙撒啊，不要因夢和夢的講解驚惶。」伯提沙撒回答說：「我主啊，願這夢歸與恨惡你的人，講解歸與你的敵人。",
   "en": "Then Daniel, whose name was Belteshazzar, was stricken mute for a while, and his thoughts troubled him. The king answered, “Belteshazzar, don’t let the dream, or the interpretation, trouble you.” Belteshazzar answered, “My lord, may the dream be for those who hate you, and its interpretation to your adversaries."
  },
  "20": {
   "zh": "你所見的樹漸長，而且堅固，高得頂天，從地極都能看見；",
   "en": "The tree that you saw, which grew, and was strong, whose height reached to the sky, and its sight to all the earth;"
  },
  "21": {
   "zh": "葉子華美，果子甚多，可作眾生的食物；田野的走獸住在其下；天空的飛鳥宿在枝上。",
   "en": "whose leaves were beautiful, and its fruit plentiful, and in it was food for all; under which the animals of the field lived, and on whose branches the birds of the sky had their habitation:"
  },
  "22": {
   "zh": "「王啊，這漸長又堅固的樹就是你。你的威勢漸長及天，你的權柄管到地極。",
   "en": "it is you, O king, that have grown and become strong; for your greatness has grown, and reaches to the sky, and your dominion to the end of the earth."
  },
  "23": {
   "zh": "王既看見一位守望的聖者從天而降，說：『將這樹砍伐毀壞，樹墩卻要留在地內，用鐵圈和銅圈箍住；在田野的青草中，讓天露滴濕，使他與地上的獸一同吃草，直到經過七期。』",
   "en": "“Whereas the king saw a watcher and a holy one coming down from the sky, and saying, ‘Cut down the tree, and destroy it; nevertheless leave the stump of its roots in the earth, even with a band of iron and brass, in the tender grass of the field, and let it be wet with the dew of the sky. Let his portion be with the animals of the field, until seven times pass over him."
  },
  "24": {
   "zh": "「王啊，講解就是這樣：臨到我主我王的事是出於至高者的命。",
   "en": "“This is the interpretation, O king, and it is the decree of the Most High, which has come on my lord the king:"
  },
  "25": {
   "zh": "你必被趕出離開世人，與野地的獸同居，吃草如牛，被天露滴濕，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。",
   "en": "that you shall be driven from men, and your dwelling shall be with the animals of the field. You shall be made to eat grass as oxen, and shall be wet with the dew of the sky, and seven times shall pass over you; until you know that the Most High rules in the kingdom of men, and gives it to whomever he will."
  },
  "26": {
   "zh": "守望者既吩咐存留樹墩，等你知道諸天掌權，以後你的國必定歸你。",
   "en": "Whereas they commanded to leave the stump of the roots of the tree; your kingdom shall be sure to you, after that you will have known that the heavens do rule."
  },
  "27": {
   "zh": "王啊，求你悅納我的諫言，以施行公義斷絕罪過，以憐憫窮人除掉罪孽，或者你的平安可以延長。」",
   "en": "Therefore, O king, let my counsel be acceptable to you, and break off your sins by righteousness, and your iniquities by showing mercy to the poor; if there may be a lengthening of your tranquility.”"
  },
  "28": {
   "zh": "這事都臨到尼布甲尼撒王。",
   "en": "All this came on the king Nebuchadnezzar."
  },
  "29": {
   "zh": "過了十二個月，他遊行在巴比倫王宮裡（原文是上）。",
   "en": "At the end of twelve months he was walking in the royal palace of Babylon."
  },
  "30": {
   "zh": "他說：「這大巴比倫不是我用大能大力建為京都，要顯我威嚴的榮耀嗎？」",
   "en": "The king spoke and said, “Is not this great Babylon, which I have built for the royal dwelling place, by the might of my power and for the glory of my majesty?”"
  },
  "31": {
   "zh": "這話在王口中尚未說完，有聲音從天降下，說：「尼布甲尼撒王啊，有話對你說，你的國位離開你了。",
   "en": "While the word was in the king’s mouth, a voice came from the sky, saying, “O king Nebuchadnezzar, to you it is spoken: ‘The kingdom has departed from you."
  },
  "32": {
   "zh": "你必被趕出離開世人，與野地的獸同居，吃草如牛，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。」",
   "en": "You shall be driven from men; and your dwelling shall be with the animals of the field. You shall be made to eat grass as oxen. Seven times shall pass over you, until you know that the Most High rules in the kingdom of men, and gives it to whomever he will.’”"
  },
  "33": {
   "zh": "當時這話就應驗在尼布甲尼撒的身上，他被趕出離開世人，吃草如牛，身被天露滴濕，頭髮長長，好像鷹毛；指甲長長，如同鳥爪。",
   "en": "This was fulfilled the same hour on Nebuchadnezzar. He was driven from men, and ate grass as oxen, and his body was wet with the dew of the sky, until his hair had grown like eagles’ feathers, and his nails like birds’ claws."
  },
  "34": {
   "zh": "日子滿足，我─尼布甲尼撒舉目望天，我的聰明復歸於我，我便稱頌至高者，讚美尊敬活到永遠的神。他的權柄是永有的；他的國存到萬代。",
   "en": "At the end of the days I, Nebuchadnezzar, lifted up my eyes to heaven, and my understanding returned to me, and I blessed the Most High, and I praised and honored him who lives forever; for his dominion is an everlasting dominion, and his kingdom from generation to generation."
  },
  "35": {
   "zh": "世上所有的居民都算為虛無；在天上的萬軍和世上的居民中，他都憑自己的意旨行事。無人能攔住他手，或問他說，你做甚麼呢？",
   "en": "All the inhabitants of the earth are reputed as nothing; and he does according to his will in the army of heaven, and among the inhabitants of the earth; and no one can stop his hand, or ask him, “What are you doing?”"
  },
  "36": {
   "zh": "那時，我的聰明復歸於我，為我國的榮耀、威嚴，和光耀也都復歸於我；並且我的謀士和大臣也來朝見我。我又得堅立在國位上，至大的權柄加增於我。",
   "en": "At the same time my understanding returned to me; and for the glory of my kingdom, my majesty and brightness returned to me. My counselors and my lords sought me; and I was established in my kingdom, and excellent greatness was added to me."
  },
  "37": {
   "zh": "現在我─尼布甲尼撒讚美、尊崇、恭敬天上的王；因為他所做的全都誠實，他所行的也都公平。那行動驕傲的，他能降為卑。",
   "en": "Now I, Nebuchadnezzar, praise and extol and honor the King of heaven; for all his works are truth, and his ways justice; and those who walk in pride he is able to abase."
  }
 },
 "5": {
  "1": {
   "zh": "伯沙撒王為他的一千大臣設擺盛筵，與這一千人對面飲酒。",
   "en": "Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand."
  },
  "2": {
   "zh": "伯沙撒歡飲之間，吩咐人將他父（或譯：祖；下同）尼布甲尼撒從耶路撒冷殿中所掠的金銀器皿拿來，王與大臣、皇后、妃嬪好用這器皿飲酒。",
   "en": "Belshazzar, while he tasted the wine, commanded that the golden and silver vessels which Nebuchadnezzar his father had taken out of the temple which was in Jerusalem be brought to him; that the king and his lords, his wives and his concubines, might drink from them."
  },
  "3": {
   "zh": "於是他們把耶路撒冷神殿庫房中所掠的金器皿拿來，王和大臣、皇后、妃嬪就用這器皿飲酒。",
   "en": "Then they brought the golden vessels that were taken out of the temple of God’s house which was at Jerusalem; and the king and his lords, his wives and his concubines, drank from them."
  },
  "4": {
   "zh": "他們飲酒，讚美金、銀、銅、鐵、木、石所造的神。",
   "en": "They drank wine, and praised the gods of gold, and of silver, of brass, of iron, of wood, and of stone."
  },
  "5": {
   "zh": "當時，忽有人的指頭顯出，在王宮與燈臺相對的粉牆上寫字。王看見寫字的指頭",
   "en": "In the same hour, the fingers of a man’s hand came out and wrote near the lamp stand on the plaster of the wall of the king’s palace. The king saw the part of the hand that wrote."
  },
  "6": {
   "zh": "就變了臉色，心意驚惶，腰骨好像脫節，雙膝彼此相碰，",
   "en": "Then the king’s face was changed in him, and his thoughts troubled him; and the joints of his thighs were loosened, and his knees struck one against another."
  },
  "7": {
   "zh": "大聲吩咐將用法術的和迦勒底人並觀兆的領進來，對巴比倫的哲士說，誰能讀這文字，把講解告訴我，他必身穿紫袍，項帶金鍊，在我國中位列第三。",
   "en": "The king cried aloud to bring in the enchanters, the Chaldeans, and the soothsayers. The king spoke and said to the wise men of Babylon, “Whoever reads this writing, and shows me its interpretation, shall be clothed with purple, and have a chain of gold about his neck, and shall be the third ruler in the kingdom.”"
  },
  "8": {
   "zh": "於是王的一切哲士都進來，卻不能讀那文字，也不能把講解告訴王。",
   "en": "Then all the king’s wise men came in; but they could not read the writing, and couldn’t make known to the king the interpretation."
  },
  "9": {
   "zh": "伯沙撒王就甚驚惶，臉色改變，他的大臣也都驚奇。",
   "en": "Then king Belshazzar was greatly troubled, and his face was changed in him, and his lords were perplexed."
  },
  "10": {
   "zh": "太后（或譯：皇后；下同）因王和他大臣所說的話，就進入宴宮，說：「願王萬歲！你心意不要驚惶，臉面不要變色。",
   "en": "The queen by reason of the words of the king and his lords came into the banquet house. The queen spoke and said, “O king, live forever; don’t let your thoughts trouble you, nor let your face be changed."
  },
  "11": {
   "zh": "在你國中有一人，他裡頭有聖神的靈，你父在世的日子，這人心中光明，又有聰明智慧，好像神的智慧。你父尼布甲尼撒王，就是王的父，立他為術士、用法術的，和迦勒底人，並觀兆的領袖。",
   "en": "There is a man in your kingdom, in whom is the spirit of the holy gods; and in the days of your father light and understanding and wisdom, like the wisdom of the gods, were found in him. The king Nebuchadnezzar your father, yes, the king, your father, made him master of the magicians, enchanters, Chaldeans, and soothsayers;"
  },
  "12": {
   "zh": "在他裡頭有美好的靈性，又有知識聰明，能圓夢，釋謎語，解疑惑。這人名叫但以理，尼布甲尼撒王又稱他為伯提沙撒，現在可以召他來，他必解明這意思。」",
   "en": "because an excellent spirit, knowledge, understanding, interpreting of dreams, showing of dark sentences, and dissolving of doubts were found in the same Daniel, whom the king named Belteshazzar. Now let Daniel be called, and he will show the interpretation.”"
  },
  "13": {
   "zh": "但以理就被領到王前。王問但以理說：「你是被擄之猶大人中的但以理嗎？就是我父王從猶大擄來的嗎？",
   "en": "Then Daniel was brought in before the king. The king spoke and said to Daniel, “Are you that Daniel of the children of the captivity of Judah, whom the king my father brought out of Judah?"
  },
  "14": {
   "zh": "我聽說你裡頭有神的靈，心中光明，又有聰明和美好的智慧。",
   "en": "I have heard of you, that the spirit of the gods is in you, and that light, understanding, and excellent wisdom are found in you."
  },
  "15": {
   "zh": "現在哲士和用法術的都領到我面前，為叫他們讀這文字，把講解告訴我，無奈他們都不能把講解說出來。",
   "en": "Now the wise men, the enchanters, have been brought in before me, that they should read this writing, and make known to me its interpretation; but they could not show the interpretation of the thing."
  },
  "16": {
   "zh": "我聽說你善於講解，能解疑惑；現在你若能讀這文字，把講解告訴我，就必身穿紫袍，項戴金鍊，在我國中位列第三。」",
   "en": "But I have heard of you, that you can give interpretations, and dissolve doubts. Now if you can read the writing, and make known to me its interpretation, you shall be clothed with purple, and have a chain of gold around your neck, and shall be the third ruler in the kingdom.”"
  },
  "17": {
   "zh": "但以理在王面前回答說：「你的贈品可以歸你自己，你的賞賜可以歸給別人；我卻要為王讀這文字，把講解告訴王。",
   "en": "Then Daniel answered before the king, “Let your gifts be to yourself, and give your rewards to another. Nevertheless, I will read the writing to the king, and make known to him the interpretation."
  },
  "18": {
   "zh": "王啊，至高的神曾將國位、大權、榮耀、威嚴賜與你父尼布甲尼撒；",
   "en": "“You, king, the Most High God gave Nebuchadnezzar your father the kingdom, and greatness, and glory, and majesty."
  },
  "19": {
   "zh": "因神所賜他的大權，各方、各國、各族的人都在他面前戰兢恐懼。他可以隨意生殺，隨意升降。",
   "en": "Because of the greatness that he gave him, all the peoples, nations, and languages trembled and feared before him. He killed whom he wanted to, and he kept alive whom he wanted to. He raised up whom he wanted to, and he put down whom he wanted to."
  },
  "20": {
   "zh": "但他心高氣傲，靈也剛愎，甚至行事狂傲，就被革去王位，奪去榮耀。",
   "en": "But when his heart was lifted up, and his spirit was hardened so that he dealt proudly, he was deposed from his kingly throne, and they took his glory from him."
  },
  "21": {
   "zh": "他被趕出離開世人，他的心變如獸心，與野驢同居，吃草如牛，身被天露滴濕，等他知道至高的神在人的國中掌權，憑自己的意旨立人治國。",
   "en": "He was driven from the sons of men, and his heart was made like the animals’, and his dwelling was with the wild donkeys. He was fed with grass like oxen, and his body was wet with the dew of the sky; until he knew that the Most High God rules in the kingdom of men, and that he sets up over it whomever he will."
  },
  "22": {
   "zh": "伯沙撒啊，你是他的兒子（或譯：孫子），你雖知道這一切，你心仍不自卑，",
   "en": "“You, his son, Belshazzar, have not humbled your heart, though you knew all this,"
  },
  "23": {
   "zh": "竟向天上的主自高，使人將他殿中的器皿拿到你面前，你和大臣、皇后、妃嬪用這器皿飲酒。你又讚美那不能看、不能聽、無知無識、金、銀、銅、鐵、木、石所造的神，卻沒有將榮耀歸與那手中有你氣息，管理你一切行動的神。",
   "en": "but have lifted up yourself against the Lord of heaven; and they have brought the vessels of his house before you, and you and your lords, your wives, and your concubines, have drunk wine from them. You have praised the gods of silver and gold, of brass, iron, wood, and stone, which don’t see, or hear, or know; and you have not glorified the God in whose hand your breath is, and whose are all your ways."
  },
  "24": {
   "zh": "因此從神那裡顯出指頭來寫這文字。",
   "en": "Then the part of the hand was sent from before him, and this writing was inscribed."
  },
  "25": {
   "zh": "「所寫的文字是：『彌尼，彌尼，提客勒，烏法珥新。』",
   "en": "“This is the writing that was inscribed: ‘MENE, MENE, TEKEL, UPHARSIN.’"
  },
  "26": {
   "zh": "講解是這樣：彌尼，就是神已經數算你國的年日到此完畢。",
   "en": "“This is the interpretation of the thing: MENE: God has counted your kingdom, and brought it to an end."
  },
  "27": {
   "zh": "提客勒，就是你被稱在天平裡，顯出你的虧欠。",
   "en": "TEKEL: you are weighed in the balances, and are found wanting."
  },
  "28": {
   "zh": "毘勒斯（與烏法珥新同義），就是你的國分裂，歸與瑪代人和波斯人。」",
   "en": "PERES: your kingdom is divided, and given to the Medes and Persians.”"
  },
  "29": {
   "zh": "伯沙撒下令，人就把紫袍給但以理穿上，把金鍊給他戴在頸項上，又傳令使他在國中位列第三。",
   "en": "Then Belshazzar commanded, and they clothed Daniel with purple, and put a chain of gold about his neck, and made proclamation concerning him, that he should be the third ruler in the kingdom."
  },
  "30": {
   "zh": "當夜，迦勒底王伯沙撒被殺。",
   "en": "In that night Belshazzar the Chaldean King was slain."
  },
  "31": {
   "zh": "米底亞人大利烏年六十二歲，取了迦勒底國。",
   "en": "Darius the Mede received the kingdom, being about sixty-two years old."
  }
 },
 "6": {
  "1": {
   "zh": "大利烏隨心所願，立一百二十個總督，治理通國。",
   "en": "It pleased Darius to set over the kingdom one hundred twenty satraps, who should be throughout the whole kingdom;"
  },
  "2": {
   "zh": "又在他們以上立總長三人（但以理在其中），使總督在他們三人面前回覆事務，免得王受虧損。",
   "en": "and over them three presidents, of whom Daniel was one; that these satraps might give account to them, and that the king should suffer no loss."
  },
  "3": {
   "zh": "因這但以理有美好的靈性，所以顯然超乎其餘的總長和總督，王又想立他治理通國。",
   "en": "Then this Daniel was distinguished above the presidents and the satraps, because an excellent spirit was in him; and the king thought to set him over the whole realm."
  },
  "4": {
   "zh": "那時，總長和總督尋找但以理誤國的把柄，為要參他；只是找不著他的錯誤過失，因他忠心辦事，毫無錯誤過失。",
   "en": "Then the presidents and the satraps sought to find occasion against Daniel as touching the kingdom; but they could find no occasion or fault, because he was faithful. There wasn’t any error or fault found in him."
  },
  "5": {
   "zh": "那些人便說：「我們要找參這但以理的把柄，除非在他神的律法中就尋不著。」",
   "en": "Then these men said, “We won’t find any occasion against this Daniel, unless we find it against him concerning the law of his God.”"
  },
  "6": {
   "zh": "於是，總長和總督紛紛聚集來見王，說：「願大利烏王萬歲！",
   "en": "Then these presidents and satraps assembled together to the king, and said thus to him, “King Darius, live forever!"
  },
  "7": {
   "zh": "國中的總長、欽差、總督、謀士，和巡撫彼此商議，要立一條堅定的禁令（或譯：求王下旨要立一條……），三十日內，不拘何人，若在王以外，或向神或向人求甚麼，就必扔在獅子坑中。",
   "en": "All the presidents of the kingdom, the deputies and the satraps, the counselors and the governors, have consulted together to establish a royal statute, and to make a strong decree, that whoever asks a petition of any god or man for thirty days, except of you, O king, he shall be cast into the den of lions."
  },
  "8": {
   "zh": "王啊，現在求你立這禁令，加蓋玉璽，使禁令決不更改；照瑪代和波斯人的例是不可更改的。」",
   "en": "Now, O king, establish the decree, and sign the writing, that it not be changed, according to the law of the Medes and Persians, which doesn’t alter.”"
  },
  "9": {
   "zh": "於是大利烏王立這禁令，加蓋玉璽。",
   "en": "Therefore king Darius signed the writing and the decree."
  },
  "10": {
   "zh": "但以理知道這禁令蓋了玉璽，就到自己家裡（他樓上的窗戶開向耶路撒冷），一日三次，雙膝跪在他神面前，禱告感謝，與素常一樣。",
   "en": "When Daniel knew that the writing was signed, he went into his house (now his windows were open in his room toward Jerusalem) and he kneeled on his knees three times a day, and prayed, and gave thanks before his God, as he did before."
  },
  "11": {
   "zh": "那些人就紛紛聚集，見但以理在他神面前祈禱懇求。",
   "en": "Then these men assembled together, and found Daniel making petition and supplication before his God."
  },
  "12": {
   "zh": "他們便進到王前，提王的禁令，說：「王啊，三十日內不拘何人，若在王以外，或向神或向人求甚麼，必被扔在獅子坑中。王不是在這禁令上蓋了玉璽麼？」王回答說：「實有這事，照瑪代和波斯人的例是不可更改的。」",
   "en": "Then they came near, and spoke before the king concerning the king’s decree: “Haven’t you signed a decree that every man who makes a petition to any god or man within thirty days, except to you, O king, shall be cast into the den of lions?” The king answered, “This thing is true, according to the law of the Medes and Persians, which doesn’t alter.”"
  },
  "13": {
   "zh": "他們對王說：「王啊，那被擄之猶大人中的但以理不理你，也不遵你蓋了玉璽的禁令，他竟一日三次祈禱。」",
   "en": "Then they answered and said before the king, “That Daniel, who is of the children of the captivity of Judah, doesn’t respect you, O king, nor the decree that you have signed, but makes his petition three times a day.”"
  },
  "14": {
   "zh": "王聽見這話，就甚愁煩，一心要救但以理，籌劃解救他，直到日落的時候。",
   "en": "Then the king, when he heard these words, was very displeased, and set his heart on Daniel to deliver him; and he labored until the going down of the sun to rescue him."
  },
  "15": {
   "zh": "那些人就紛紛聚集來見王，說：「王啊，當知道瑪代人和波斯人有例，凡王所立的禁令和律例都不可更改。」",
   "en": "Then these men assembled together to the king, and said to the king, “Know, O king, that it is a law of the Medes and Persians, that no decree nor statute which the king establishes may be changed.”"
  },
  "16": {
   "zh": "王下令，人就把但以理帶來，扔在獅子坑中。王對但以理說：「你所常事奉的神，他必救你。」",
   "en": "Then the king commanded, and they brought Daniel, and cast him into the den of lions. The king spoke and said to Daniel, “Your God whom you serve continually, he will deliver you.”"
  },
  "17": {
   "zh": "有人搬石頭放在坑口，王用自己的璽和大臣的印，封閉那坑，使懲辦但以理的事毫無更改。",
   "en": "A stone was brought, and laid on the mouth of the den; and the king sealed it with his own signet, and with the signet of his lords; that nothing might be changed concerning Daniel."
  },
  "18": {
   "zh": "王回宮，終夜禁食，無人拿樂器到他面前，並且睡不著覺。",
   "en": "Then the king went to his palace, and passed the night fasting. No musical instruments were brought before him; and his sleep fled from him."
  },
  "19": {
   "zh": "次日黎明，王就起來，急忙往獅子坑那裡去。",
   "en": "Then the king arose very early in the morning, and went in haste to the den of lions."
  },
  "20": {
   "zh": "臨近坑邊，哀聲呼叫但以理，對但以理說：「永生神的僕人但以理啊，你所常事奉的神能救你脫離獅子嗎？」",
   "en": "When he came near to the den to Daniel, he cried with a troubled voice. The king spoke and said to Daniel, “Daniel, servant of the living God, is your God, whom you serve continually, able to deliver you from the lions?”"
  },
  "21": {
   "zh": "但以理對王說：「願王萬歲！",
   "en": "Then Daniel said to the king, “O king, live forever!"
  },
  "22": {
   "zh": "我的神差遣使者，封住獅子的口，叫獅子不傷我；因我在神面前無辜，我在王面前也沒有行過虧損的事。」",
   "en": "My God has sent his angel, and has shut the lions’ mouths, and they have not hurt me; because as before him innocence was found in me; and also before you, O king, I have done no harm.”"
  },
  "23": {
   "zh": "王就甚喜樂，吩咐人將但以理從坑裡繫上來。於是但以理從坑裡被繫上來，身上毫無傷損，因為信靠他的神。",
   "en": "Then the king was exceedingly glad, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no kind of harm was found on him, because he had trusted in his God."
  },
  "24": {
   "zh": "王下令，人就把那些控告但以理的人，連他們的妻子兒女都帶來，扔在獅子坑中。他們還沒有到坑底，獅子就抓住（原文是勝了）他們，咬碎他們的骨頭。",
   "en": "The king commanded, and they brought those men who had accused Daniel, and they cast them into the den of lions, them, their children, and their wives; and the lions mauled them, and broke all their bones in pieces, before they came to the bottom of the den."
  },
  "25": {
   "zh": "那時，大利烏王傳旨，曉諭住在全地各方、各國、各族的人說：「願你們大享平安！",
   "en": "Then king Darius wrote to all the peoples, nations, and languages, who dwell in all the earth: “Peace be multiplied to you."
  },
  "26": {
   "zh": "現在我降旨曉諭我所統轄的全國人民，要在但以理的神面前，戰兢恐懼。因為他是永遠長存的活神，他的國永不敗壞；他的權柄永存無極！",
   "en": "“I make a decree that in all the dominion of my kingdom men tremble and fear before the God of Daniel; “for he is the living God, and steadfast forever. His kingdom is that which will not be destroyed. His dominion will be even to the end."
  },
  "27": {
   "zh": "他護庇人，搭救人，在天上地下施行神蹟奇事，救了但以理脫離獅子的口。」",
   "en": "He delivers and rescues. He works signs and wonders in heaven and in earth, who has delivered Daniel from the power of the lions.”"
  },
  "28": {
   "zh": "如此，這但以理，當大利烏王在位的時候和波斯王古列在位的時候，大享亨通。",
   "en": "So this Daniel prospered in the reign of Darius, and in the reign of Cyrus the Persian."
  }
 },
 "7": {
  "1": {
   "zh": "巴比倫王伯沙撒元年，但以理在床上做夢，見了腦中的異象，就記錄這夢，述說其中的大意。",
   "en": "In the first year of Belshazzar king of Babylon Daniel had a dream and visions of his head on his bed. Then he wrote the dream and told the sum of the matters."
  },
  "2": {
   "zh": "但以理說：我夜裡見異象，看見天的四風陡起，颳在大海之上。",
   "en": "Daniel spoke and said, “I saw in my vision by night, and, behold, the four winds of the sky broke out on the great sea."
  },
  "3": {
   "zh": "有四個大獸從海中上來，形狀各有不同：",
   "en": "Four great animals came up from the sea, different from one another."
  },
  "4": {
   "zh": "頭一個像獅子，有鷹的翅膀；我正觀看的時候，獸的翅膀被拔去，獸從地上得立起來，用兩腳站立，像人一樣，又得了人心。",
   "en": "“The first was like a lion, and had eagle’s wings. I watched until its wings were plucked, and it was lifted up from the earth, and made to stand on two feet as a man. A man’s heart was given to it."
  },
  "5": {
   "zh": "又有一獸如熊，就是第二獸，旁跨而坐，口齒內啣著三根肋骨。有吩咐這獸的說：起來吞吃多肉。",
   "en": "“Behold, there was another animal, a second, like a bear. It was raised up on one side, and three ribs were in its mouth between its teeth. They said this to it: ‘Arise! Devour much flesh!’"
  },
  "6": {
   "zh": "此後我觀看，又有一獸如豹，背上有鳥的四個翅膀；這獸有四個頭，又得了權柄。",
   "en": "“After this I saw, and behold, another, like a leopard, which had on its back four wings of a bird. The animal also had four heads; and dominion was given to it."
  },
  "7": {
   "zh": "其後我在夜間的異象中觀看，見第四獸甚是可怕，極其強壯，大有力量，有大鐵牙，吞吃嚼碎，所剩下的用腳踐踏。這獸與前三獸大不相同，頭有十角。",
   "en": "“After this I saw in the night visions, and, behold, there was a fourth animal, awesome and powerful, and exceedingly strong. It had great iron teeth. It devoured and broke in pieces, and stamped the residue with its feet. It was different than all the animals that were before it. It had ten horns."
  },
  "8": {
   "zh": "我正觀看這些角，見其中又長起一個小角；先前的角中有三角在這角前，連根被牠拔出來。這角有眼，像人的眼，有口說誇大的話。",
   "en": "“I considered the horns, and behold, there came up among them another horn, a little one, before which three of the first horns were plucked up by the roots: and behold, in this horn were eyes like the eyes of a man, and a mouth speaking great things."
  },
  "9": {
   "zh": "我觀看，見有寶座設立，上頭坐著亙古常在者。他的衣服潔白如雪，頭髮如純淨的羊毛。寶座乃火焰，其輪乃烈火。",
   "en": "“I watched until thrones were placed, and one who was ancient of days sat. His clothing was white as snow, and the hair of his head like pure wool. His throne was fiery flames, and its wheels burning fire."
  },
  "10": {
   "zh": "從他面前有火，像河發出；事奉他的有千千，在他面前侍立的有萬萬；他坐著要行審判，案卷都展開了。",
   "en": "A fiery stream issued and came out from before him. Thousands of thousands ministered to him. Ten thousand times ten thousand stood before him. The judgment was set. The books were opened."
  },
  "11": {
   "zh": "那時我觀看，見那獸因小角說誇大話的聲音被殺，身體損壞，扔在火中焚燒。",
   "en": "“I watched at that time because of the voice of the great words which the horn spoke. I watched even until the animal was slain, and its body destroyed, and it was given to be burned with fire."
  },
  "12": {
   "zh": "其餘的獸，權柄都被奪去，生命卻仍存留，直到所定的時候和日期。",
   "en": "As for the rest of the animals, their dominion was taken away; yet their lives were prolonged for a season and a time."
  },
  "13": {
   "zh": "我在夜間的異象中觀看，見有一位像人子的，駕著天雲而來，被領到亙古常在者面前，",
   "en": "“I saw in the night visions, and behold, there came with the clouds of the sky one like a son of man, and he came even to the ancient of days, and they brought him near before him."
  },
  "14": {
   "zh": "得了權柄、榮耀、國度，使各方、各國、各族的人都事奉他。他的權柄是永遠的，不能廢去；他的國必不敗壞。",
   "en": "Dominion was given him, and glory, and a kingdom, that all the peoples, nations, and languages should serve him. His dominion is an everlasting dominion, which will not pass away, and his kingdom that which will not be destroyed."
  },
  "15": {
   "zh": "至於我─但以理，我的靈在我裡面愁煩，我腦中的異象使我驚惶。",
   "en": "“As for me, Daniel, my spirit was grieved within my body, and the visions of my head troubled me."
  },
  "16": {
   "zh": "我就近一位侍立者，問他這一切的真情。他就告訴我，將那事的講解給我說明。",
   "en": "I came near to one of those who stood by, and asked him the truth concerning all this. “So he told me, and made me know the interpretation of the things."
  },
  "17": {
   "zh": "這四個大獸就是四王將要在世上興起。",
   "en": "‘These great animals, which are four, are four kings, who will arise out of the earth."
  },
  "18": {
   "zh": "然而，至高者的聖民，必要得國享受，直到永永遠遠。",
   "en": "But the saints of the Most High will receive the kingdom, and possess the kingdom forever, even forever and ever.’"
  },
  "19": {
   "zh": "那時我願知道第四獸的真情，牠為何與那三獸的真情大不相同，甚是可怕，有鐵牙銅爪，吞吃嚼碎，所剩下的用腳踐踏；",
   "en": "“Then I desired to know the truth concerning the fourth animal, which was different than all of them, exceedingly terrible, whose teeth were of iron, and its nails of brass; which devoured, broke in pieces, and stamped the residue with its feet;"
  },
  "20": {
   "zh": "頭有十角和那另長的一角，在這角前有三角被牠打落。這角有眼，有說誇大話的口，形狀強橫，過於牠的同類。",
   "en": "and concerning the ten horns that were on its head, and the other horn which came up, and before which three fell, even that horn that had eyes, and a mouth that spoke great things, whose look was more stout than its fellows."
  },
  "21": {
   "zh": "我觀看，見這角與聖民爭戰，勝了他們。",
   "en": "I saw, and the same horn made war with the saints, and prevailed against them,"
  },
  "22": {
   "zh": "直到亙古常在者來給至高者的聖民伸冤，聖民得國的時候就到了。",
   "en": "until the ancient of days came, and judgment was given to the saints of the Most High, and the time came that the saints possessed the kingdom."
  },
  "23": {
   "zh": "那侍立者這樣說：第四獸就是世上必有的第四國，與一切國大不相同，必吞吃全地，並且踐踏嚼碎。",
   "en": "“Thus he said, ‘The fourth animal will be a fourth kingdom on earth, which will be different than all the kingdoms, and will devour the whole earth, and will tread it down, and break it in pieces."
  },
  "24": {
   "zh": "至於那十角，就是從這國中必興起的十王，後來又興起一王，與先前的不同；他必制伏三王。",
   "en": "As for the ten horns, ten kings will arise out of this kingdom. Another will arise after them; and he will be different than the former, and he will put down three kings."
  },
  "25": {
   "zh": "他必向至高者說誇大的話，必折磨至高者的聖民，必想改變節期和律法。聖民必交付他手一載、二載、半載。",
   "en": "He will speak words against the Most High, and will wear out the saints of the Most High. He will plan to change the times and the law; and they will be given into his hand until a time and times and half a time."
  },
  "26": {
   "zh": "然而，審判者必坐著行審判；他的權柄必被奪去，毀壞，滅絕，一直到底。",
   "en": "“‘But the judgment will be set, and they will take away his dominion, to consume and to destroy it to the end."
  },
  "27": {
   "zh": "國度、權柄，和天下諸國的大權必賜給至高者的聖民。他的國是永遠的；一切掌權的都必事奉他，順從他。",
   "en": "The kingdom and the dominion, and the greatness of the kingdoms under the whole sky, will be given to the people of the saints of the Most High. His kingdom is an everlasting kingdom, and all dominions will serve and obey him.’"
  },
  "28": {
   "zh": "那事至此完畢。至於我─但以理，心中甚是驚惶，臉色也改變了，卻將那事存記在心。",
   "en": "“Here is the end of the matter. As for me, Daniel, my thoughts much troubled me, and my face was changed in me; but I kept the matter in my heart.”"
  }
 },
 "8": {
  "1": {
   "zh": "伯沙撒王在位第三年，有異象現與我─但以理，是在先前所見的異象之後。",
   "en": "In the third year of the reign of king Belshazzar a vision appeared to me, even to me, Daniel, after that which appeared to me at the first."
  },
  "2": {
   "zh": "我見了異象的時候，我以為在以攔省書珊城（或譯：宮）中；我見異象又如在烏萊河邊。",
   "en": "I saw the vision. Now it was so, that when I saw, I was in the citadel of Susa, which is in the province of Elam. I saw in the vision, and I was by the river Ulai."
  },
  "3": {
   "zh": "我舉目觀看，見有雙角的公綿羊站在河邊，兩角都高。這角高過那角，更高的是後長的。",
   "en": "Then I lifted up my eyes, and saw, and behold, there stood before the river a ram which had two horns. The two horns were high; but one was higher than the other, and the higher came up last."
  },
  "4": {
   "zh": "我見那公綿羊往西、往北、往南牴觸。獸在牠面前都站立不住，也沒有能救護脫離牠手的；但牠任意而行，自高自大。",
   "en": "I saw the ram pushing westward, northward, and southward. No animals could stand before him. There wasn’t any who could deliver out of his hand; but he did according to his will, and magnified himself."
  },
  "5": {
   "zh": "我正思想的時候，見有一隻公山羊從西而來，遍行全地，腳不沾塵。這山羊兩眼當中有一非常的角。",
   "en": "As I was considering, behold, a male goat came from the west over the surface of the whole earth, and didn’t touch the ground. The goat had a notable horn between his eyes."
  },
  "6": {
   "zh": "牠往我所看見、站在河邊有雙角的公綿羊那裡去，大發忿怒，向牠直闖。",
   "en": "He came to the ram that had the two horns, which I saw standing before the river, and ran on him in the fury of his power."
  },
  "7": {
   "zh": "我見公山羊就近公綿羊，向牠發烈怒，牴觸牠，折斷牠的兩角。綿羊在牠面前站立不住；牠將綿羊觸倒在地，用腳踐踏，沒有能救綿羊脫離牠手的。",
   "en": "I saw him come close to the ram, and he was moved with anger against him, and struck the ram, and broke his two horns. There was no power in the ram to stand before him; but he cast him down to the ground, and trampled on him. There was no one who could deliver the ram out of his hand."
  },
  "8": {
   "zh": "這山羊極其自高自大，正強盛的時候，那大角折斷了，又在角根上向天的四方（原文是風）長出四個非常的角來。",
   "en": "The male goat magnified himself exceedingly. When he was strong, the great horn was broken; and instead of it there came up four notable horns toward the four winds of the sky."
  },
  "9": {
   "zh": "四角之中有一角長出一個小角，向南、向東、向榮美之地，漸漸成為強大。",
   "en": "Out of one of them came out a little horn, which grew exceeding great, toward the south, and toward the east, and toward the glorious land."
  },
  "10": {
   "zh": "牠漸漸強大，高及天象，將些天象和星宿拋落在地，用腳踐踏。",
   "en": "It grew great, even to the army of the sky; and it cast down some of the army and of the stars to the ground, and trampled on them."
  },
  "11": {
   "zh": "並且牠自高自大，以為高及天象之君；除掉常獻給君的燔祭，毀壞君的聖所。",
   "en": "Yes, it magnified itself, even to the prince of the army; and it took away from him the continual burnt offering, and the place of his sanctuary was cast down."
  },
  "12": {
   "zh": "因罪過的緣故，有軍旅和常獻的燔祭交付牠。牠將真理拋在地上，任意而行，無不順利。",
   "en": "The army was given over to it together with the continual burnt offering through disobedience. It cast down truth to the ground, and it did its pleasure and prospered."
  },
  "13": {
   "zh": "我聽見有一位聖者說話，又有一位聖者問那說話的聖者說：「這除掉常獻的燔祭和施行毀壞的罪過，將聖所與軍旅（或譯：以色列的軍）踐踏的異象，要到幾時才應驗呢？」",
   "en": "Then I heard a holy one speaking; and another holy one said to that certain one who spoke, “How long will the vision about the continual burnt offering, and the disobedience that makes desolate, to give both the sanctuary and the army to be trodden under foot be?”"
  },
  "14": {
   "zh": "他對我說：「到二千三百日，聖所就必潔淨。」",
   "en": "He said to me, “To two thousand and three hundred evenings and mornings. Then the sanctuary will be cleansed.”"
  },
  "15": {
   "zh": "我─但以理見了這異象，願意明白其中的意思。忽有一位形狀像人的站在我面前。",
   "en": "When I, even I Daniel, had seen the vision, I sought to understand it. Then behold, there stood before me something like the appearance of a man."
  },
  "16": {
   "zh": "我又聽見烏萊河兩岸中有人聲呼叫說：「加百列啊，要使此人明白這異象。」",
   "en": "I heard a man’s voice between the banks of the Ulai, which called, and said, “Gabriel, make this man understand the vision.”"
  },
  "17": {
   "zh": "他便來到我所站的地方。他一來，我就驚慌俯伏在地；他對我說：「人子啊，你要明白，因為這是關乎末後的異象。」",
   "en": "So he came near where I stood; and when he came, I was frightened, and fell on my face; but he said to me, “Understand, son of man; for the vision belongs to the time of the end.”"
  },
  "18": {
   "zh": "他與我說話的時候，我面伏在地沉睡；他就摸我，扶我站起來，",
   "en": "Now as he was speaking with me, I fell into a deep sleep with my face toward the ground; but he touched me, and set me upright."
  },
  "19": {
   "zh": "說：「我要指示你惱怒臨完必有的事，因為這是關乎末後的定期。",
   "en": "He said, “Behold, I will make you know what will be in the latter time of the indignation; for it belongs to the appointed time of the end."
  },
  "20": {
   "zh": "你所看見雙角的公綿羊，就是瑪代和波斯王。",
   "en": "The ram which you saw, that had the two horns, they are the kings of Media and Persia."
  },
  "21": {
   "zh": "那公山羊就是希臘王（希臘：原文是雅完；下同）；兩眼當中的大角就是頭一王。",
   "en": "The rough male goat is the king of Greece. The great horn that is between his eyes is the first king."
  },
  "22": {
   "zh": "至於那折斷了的角，在其根上又長出四角，這四角就是四國，必從這國裡興起來，只是權勢都不及他。",
   "en": "As for that which was broken, in the place where four stood up, four kingdoms will stand up out of the nation, but not with his power."
  },
  "23": {
   "zh": "這四國末時，犯法的人罪惡滿盈，必有一王興起，面貌凶惡，能用雙關的詐語。",
   "en": "“In the latter time of their kingdom, when the transgressors have come to the full, a king of fierce face, and understanding dark sentences, will stand up."
  },
  "24": {
   "zh": "他的權柄必大，卻不是因自己的能力；他必行非常的毀滅，事情順利，任意而行；又必毀滅有能力的和聖民。",
   "en": "His power will be mighty, but not by his own power. He will destroy awesomely, and will prosper in what he does. He will destroy the mighty ones and the holy people."
  },
  "25": {
   "zh": "他用權術成就手中的詭計，心裡自高自大，在人坦然無備的時候，毀滅多人；又要站起來攻擊萬君之君，至終卻非因人手而滅亡。",
   "en": "Through his policy he will cause deceit to prosper in his hand. He will magnify himself in his heart, and he will destroy many in their security. He will also stand up against the prince of princes; but he will be broken without hand."
  },
  "26": {
   "zh": "所說二千三百日的異象是真的，但你要將這異象封住，因為關乎後來許多的日子。」",
   "en": "“The vision of the evenings and mornings which has been told is true; but seal up the vision, for it belongs to many days to come.”"
  },
  "27": {
   "zh": "於是我─但以理昏迷不醒，病了數日，然後起來辦理王的事務。我因這異象驚奇，卻無人能明白其中的意思。",
   "en": "I, Daniel, fainted, and was sick for some days. Then I rose up, and did the king’s business. I wondered at the vision, but no one understood it."
  }
 },
 "9": {
  "1": {
   "zh": "瑪代族亞哈隨魯的兒子大利烏立為迦勒底國的王元年，",
   "en": "In the first year of Darius the son of Ahasuerus, of the offspring of the Medes, who was made king over the realm of the Chaldeans,"
  },
  "2": {
   "zh": "就是他在位第一年，我但以理從書上得知耶和華的話臨到先知耶利米，論耶路撒冷荒涼的年數，七十年為滿。",
   "en": "in the first year of his reign I, Daniel, understood by the books the number of the years about which Yahweh’s word came to Jeremiah the prophet, for the accomplishing of the desolations of Jerusalem, even seventy years."
  },
  "3": {
   "zh": "我便禁食，披麻蒙灰，定意向主神祈禱懇求。",
   "en": "I set my face to the Lord God, to seek by prayer and petitions, with fasting and sackcloth and ashes."
  },
  "4": {
   "zh": "我向耶和華─我的神祈禱、認罪，說：「主啊，大而可畏的神，向愛主、守主誡命的人守約施慈愛。",
   "en": "I prayed to Yahweh my God, and made confession, and said, “Oh, Lord, the great and dreadful God, who keeps covenant and loving kindness with those who love him and keep his commandments,"
  },
  "5": {
   "zh": "我們犯罪作孽，行惡叛逆，偏離你的誡命典章，",
   "en": "we have sinned, and have dealt perversely, and have done wickedly, and have rebelled, even turning aside from your precepts and from your ordinances."
  },
  "6": {
   "zh": "沒有聽從你僕人眾先知奉你名向我們君王、首領、列祖，和國中一切百姓所說的話。",
   "en": "We haven’t listened to your servants the prophets, who spoke in your name to our kings, our princes, and our fathers, and to all the people of the land."
  },
  "7": {
   "zh": "主啊，你是公義的，我們是臉上蒙羞的；因我們猶大人和耶路撒冷的居民，並以色列眾人，或在近處，或在遠處，被你趕到各國的人，都得罪了你，正如今日一樣。",
   "en": "“Lord, righteousness belongs to you, but to us confusion of face, as it is today; to the men of Judah, and to the inhabitants of Jerusalem, and to all Israel, who are near, and who are far off, through all the countries where you have driven them, because of their trespass that they have trespassed against you."
  },
  "8": {
   "zh": "主啊，我們和我們的君王、首領、列祖因得罪了你，就都臉上蒙羞。",
   "en": "Lord, to us belongs confusion of face, to our kings, to our princes, and to our fathers, because we have sinned against you."
  },
  "9": {
   "zh": "主─我們的神是憐憫饒恕人的，我們卻違背了他，",
   "en": "To the Lord our God belong mercies and forgiveness; for we have rebelled against him."
  },
  "10": {
   "zh": "也沒有聽從耶和華─我們神的話，沒有遵行他藉僕人眾先知向我們所陳明的律法。",
   "en": "We haven’t obeyed Yahweh our God’s voice, to walk in his laws, which he set before us by his servants the prophets."
  },
  "11": {
   "zh": "以色列眾人都犯了你的律法，偏行，不聽從你的話；因此，在你僕人摩西律法上所寫的咒詛和誓言都傾在我們身上，因我們得罪了神。",
   "en": "Yes, all Israel have transgressed your law, turning aside, that they should not obey your voice. “Therefore the curse and the oath written in the law of Moses the servant of God has been poured out on us; for we have sinned against him."
  },
  "12": {
   "zh": "他使大災禍臨到我們，成就了警戒我們和審判我們官長的話；原來在普天之下未曾行過像在耶路撒冷所行的。",
   "en": "He has confirmed his words, which he spoke against us, and against our judges who judged us, by bringing on us a great evil; for under the whole sky, such has not been done as has been done to Jerusalem."
  },
  "13": {
   "zh": "這一切災禍臨到我們身上是照摩西律法上所寫的，我們卻沒有求耶和華─我們神的恩典，使我們回頭離開罪孽，明白你的真理。",
   "en": "As it is written in the law of Moses, all this evil has come on us. Yet have we not entreated the favor of Yahweh our God, that we should turn from our iniquities, and have discernment in your truth."
  },
  "14": {
   "zh": "所以耶和華留意使這災禍臨到我們身上，因為耶和華─我們的神在他所行的事上都是公義；我們並沒有聽從他的話。",
   "en": "Therefore Yahweh has watched over the evil, and brought it on us; for Yahweh our God is righteous in all his works which he does, and we have not obeyed his voice."
  },
  "15": {
   "zh": "主─我們的神啊，你曾用大能的手領你的子民出埃及地，使自己得了名，正如今日一樣。我們犯了罪，作了惡。",
   "en": "“Now, Lord our God, who has brought your people out of the land of Egypt with a mighty hand, and have gotten yourself renown, as it is today; we have sinned. We have done wickedly."
  },
  "16": {
   "zh": "主啊，求你按你的大仁大義，使你的怒氣和忿怒轉離你的城耶路撒冷，就是你的聖山。耶路撒冷和你的子民，因我們的罪惡和我們列祖的罪孽被四圍的人羞辱。",
   "en": "Lord, according to all your righteousness, let your anger and please let your wrath be turned away from your city Jerusalem, your holy mountain; because for our sins, and for the iniquities of our fathers, Jerusalem and your people have become a reproach to all who are around us."
  },
  "17": {
   "zh": "我們的神啊，現在求你垂聽僕人的祈禱懇求，為自己使臉光照你荒涼的聖所。",
   "en": "“Now therefore, our God, listen to the prayer of your servant, and to his petitions, and cause your face to shine on your sanctuary that is desolate, for the Lord’s sake."
  },
  "18": {
   "zh": "我的神啊，求你側耳而聽，睜眼而看，眷顧我們荒涼之地和稱為你名下的城。我們在你面前懇求，原不是因自己的義，乃因你的大憐憫。",
   "en": "My God, turn your ear, and hear. Open your eyes, and see our desolations, and the city which is called by your name; for we do not present our petitions before you for our righteousness, but for your great mercies’ sake."
  },
  "19": {
   "zh": "求主垂聽，求主赦免，求主應允而行，為你自己不要遲延。我的神啊，因這城和這民都是稱為你名下的。」",
   "en": "Lord, hear. Lord, forgive. Lord, listen and do. Don’t defer, for your own sake, my God, because your city and your people are called by your name.”"
  },
  "20": {
   "zh": "我說話，禱告，承認我的罪和本國之民以色列的罪，為我神的聖山，在耶和華─我神面前懇求。",
   "en": "While I was speaking, and praying, and confessing my sin and the sin of my people Israel, and presenting my supplication before Yahweh my God for the holy mountain of my God;"
  },
  "21": {
   "zh": "我正禱告的時候，先前在異象中所見的那位加百列，奉命迅速飛來，約在獻晚祭的時候，按手在我身上。",
   "en": "yes, while I was speaking in prayer, the man Gabriel, whom I had seen in the vision at the beginning, being caused to fly swiftly, touched me about the time of the evening offering."
  },
  "22": {
   "zh": "他指教我說：「但以理啊，現在我出來要使你有智慧，有聰明。",
   "en": "He instructed me, and talked with me, and said, Daniel, “I have now come to give you wisdom and understanding."
  },
  "23": {
   "zh": "你初懇求的時候，就發出命令，我來告訴你，因你大蒙眷愛；所以你要思想明白這以下的事和異象。",
   "en": "At the beginning of your petitions the commandment went out, and I have come to tell you; for you are greatly beloved. Therefore consider the matter, and understand the vision."
  },
  "24": {
   "zh": "「為你本國之民和你聖城，已經定了七十個七。要止住罪過，除淨罪惡，贖盡罪孽，引進（或譯：彰顯）永義，封住異象和預言，並膏至聖者（者：或譯所）。",
   "en": "“Seventy weeks are decreed on your people and on your holy city, to finish disobedience, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up vision and prophecy, and to anoint the most holy."
  },
  "25": {
   "zh": "你當知道，當明白，從出令重新建造耶路撒冷，直到有受膏君的時候，必有七個七和六十二個七。正在艱難的時候，耶路撒冷城連街帶濠都必重新建造。",
   "en": "“Know therefore and discern that from the going out of the commandment to restore and to build Jerusalem to the Anointed One, the prince, will be seven weeks and sixty-two weeks. It will be built again, with street and moat, even in troubled times."
  },
  "26": {
   "zh": "過了六十二個七，那（或譯：有）受膏者必被剪除，一無所有；必有一王的民來毀滅這城和聖所，至終必如洪水沖沒。必有爭戰，一直到底，荒涼的事已經定了。",
   "en": "After the sixty-two weeks the Anointed One will be cut off, and will have nothing. The people of the prince who come will destroy the city and the sanctuary. Its end will be with a flood, and war will be even to the end. Desolations are determined."
  },
  "27": {
   "zh": "一七之內，他必與許多人堅定盟約；一七之半，他必使祭祀與供獻止息。那行毀壞可憎的（或譯：使地荒涼的）如飛而來，並且有忿怒傾在那行毀壞的身上（或譯：傾在那荒涼之地），直到所定的結局。」",
   "en": "He will make a firm covenant with many for one week. In the middle of the week he will cause the sacrifice and the offering to cease. On the wing of abominations will come one who makes desolate; and even to the full end, and that determined, wrath will be poured out on the desolate.”"
  }
 },
 "10": {
  "1": {
   "zh": "波斯王古列第三年，有事顯給稱為伯提沙撒的但以理。這事是真的，是指著大爭戰；但以理通達這事，明白這異象。",
   "en": "In the third year of Cyrus king of Persia a thing was revealed to Daniel, whose name was called Belteshazzar; and the thing was true, even a great warfare. He understood the thing, and had understanding of the vision."
  },
  "2": {
   "zh": "當那時，我─但以理悲傷了三個七日。",
   "en": "In those days I, Daniel, was mourning three whole weeks."
  },
  "3": {
   "zh": "美味我沒有吃，酒肉沒有入我的口，也沒有用油抹我的身，直到滿了三個七日。",
   "en": "I ate no pleasant bread. No meat or wine came into my mouth. I didn’t anoint myself at all, until three whole weeks were fulfilled."
  },
  "4": {
   "zh": "正月二十四日，我在底格里斯大河邊，",
   "en": "In the twenty-fourth day of the first month, as I was by the side of the great river, which is Hiddekel,"
  },
  "5": {
   "zh": "舉目觀看，見有一人身穿細麻衣，腰束烏法精金帶。",
   "en": "I lifted up my eyes, and looked, and behold, there was a man clothed in linen, whose thighs were adorned with pure gold of Uphaz."
  },
  "6": {
   "zh": "他身體如水蒼玉，面貌如閃電，眼目如火把，手和腳如光明的銅，說話的聲音如大眾的聲音。",
   "en": "His body also was like the beryl, and his face as the appearance of lightning, and his eyes as flaming torches. His arms and his feet were like burnished brass. The voice of his words was like the voice of a multitude."
  },
  "7": {
   "zh": "這異象惟有我─但以理一人看見，同著我的人沒有看見。他們卻大大戰兢，逃跑隱藏，",
   "en": "I, Daniel, alone saw the vision; for the men who were with me didn’t see the vision; but a great quaking fell on them, and they fled to hide themselves."
  },
  "8": {
   "zh": "只剩下我一人。我見了這大異象便渾身無力，面貌失色，毫無氣力。",
   "en": "So I was left alone, and saw this great vision. No strength remained in me; for my comeliness was turned in me into corruption, and I retained no strength."
  },
  "9": {
   "zh": "我卻聽見他說話的聲音，一聽見就面伏在地沉睡了。",
   "en": "Yet I heard the voice of his words. When I heard the voice of his words, then I fell into a deep sleep on my face, with my face toward the ground."
  },
  "10": {
   "zh": "忽然，有一手按在我身上，使我用膝和手掌支持微起。",
   "en": "Behold, a hand touched me, which set me on my knees and on the palms of my hands."
  },
  "11": {
   "zh": "他對我說：「大蒙眷愛的但以理啊，要明白我與你所說的話，只管站起來，因為我現在奉差遣來到你這裡。」他對我說這話，我便戰戰兢兢地立起來。",
   "en": "He said to me, Daniel, you greatly beloved man, understand the words that I speak to you, and stand upright; for I have been sent to you, now. When he had spoken this word to me, I stood trembling."
  },
  "12": {
   "zh": "他就說：「但以理啊，不要懼怕！因為從你第一日專心求明白將來的事，又在你神面前刻苦己心，你的言語已蒙應允；我是因你的言語而來。",
   "en": "Then he said to me, “Don’t be afraid, Daniel; for from the first day that you set your heart to understand, and to humble yourself before your God, your words were heard. I have come for your words’ sake."
  },
  "13": {
   "zh": "但波斯國的魔君攔阻我二十一日。忽然有大君（就是天使長；二十一節同）中的一位米迦勒來幫助我，我就停留在波斯諸王那裡。",
   "en": "But the prince of the kingdom of Persia withstood me twenty-one days; but, behold, Michael, one of the chief princes, came to help me because I remained there with the kings of Persia."
  },
  "14": {
   "zh": "現在我來，要使你明白本國之民日後必遭遇的事，因為這異象關乎後來許多的日子。」",
   "en": "Now I have come to make you understand what will happen to your people in the latter days; for the vision is yet for many days.”"
  },
  "15": {
   "zh": "他向我這樣說，我就臉面朝地，啞口無聲。",
   "en": "When he had spoken these words to me, I set my face toward the ground, and was mute."
  },
  "16": {
   "zh": "不料，有一位像人的，摸我的嘴唇，我便開口向那站在我面前的說：「我主啊，因見這異象，我大大愁苦，毫無氣力。",
   "en": "Behold, one in the likeness of the sons of men touched my lips. Then I opened my mouth, and spoke and said to him who stood before me, “My lord, by reason of the vision my sorrows have overtaken me, and I retain no strength."
  },
  "17": {
   "zh": "我主的僕人怎能與我主說話呢？我一見異象就渾身無力，毫無氣息。」",
   "en": "For how can the servant of this my lord talk with this my lord? For as for me, immediately there remained no strength in me. There was no breath left in me.”"
  },
  "18": {
   "zh": "有一位形狀像人的又摸我，使我有力量。",
   "en": "Then one like the appearance of a man touched me again, and he strengthened me."
  },
  "19": {
   "zh": "他說：「大蒙眷愛的人哪，不要懼怕，願你平安！你總要堅強。」他一向我說話，我便覺得有力量，說：「我主請說，因你使我有力量。」",
   "en": "He said, “Greatly beloved man, don’t be afraid. Peace be to you. Be strong. Yes, be strong.” When he spoke to me, I was strengthened, and said, “Let my lord speak; for you have strengthened me.”"
  },
  "20": {
   "zh": "他就說：「你知道我為何來見你嗎？現在我要回去與波斯的魔君爭戰，我去後，希臘（原文是雅完）的魔君必來。",
   "en": "Then he said, “Do you know why I have come to you? Now I will return to fight with the prince of Persia. When I go out, behold, the prince of Greece will come."
  },
  "21": {
   "zh": "但我要將那錄在真確書上的事告訴你。除了你們的大君米迦勒之外，沒有幫助我抵擋這兩魔君的。」",
   "en": "But I will tell you that which is inscribed in the writing of truth. There is no one who holds with me against these, but Michael your prince."
  }
 },
 "11": {
  "1": {
   "zh": "又說：「當瑪代王大利烏元年，我曾起來扶助米迦勒，使他堅強。",
   "en": "“As for me, in the first year of Darius the Mede, I stood up to confirm and strengthen him."
  },
  "2": {
   "zh": "現在我將真事指示你：波斯還有三王興起，第四王必富足遠勝諸王。他因富足成為強盛，就必激動大眾攻擊希臘國。",
   "en": "“Now will I show you the truth. Behold, three more kings will stand up in Persia; and the fourth will be far richer than all of them. When he has grown strong through his riches, he will stir up all against the realm of Greece."
  },
  "3": {
   "zh": "必有一個勇敢的王興起，執掌大權，隨意而行。",
   "en": "A mighty king will stand up, who will rule with great dominion, and do according to his will."
  },
  "4": {
   "zh": "他興起的時候，他的國必破裂，向天的四方（方：原文是風）分開，卻不歸他的後裔，治國的權勢也都不及他；因為他的國必被拔出，歸與他後裔之外的人。",
   "en": "When he stands up, his kingdom will be broken, and will be divided toward the four winds of the sky, but not to his posterity, nor according to his dominion with which he ruled; for his kingdom will be plucked up, even for others besides these."
  },
  "5": {
   "zh": "南方的王必強盛，他將帥中必有一個比他更強盛，執掌權柄，他的權柄甚大。",
   "en": "“The king of the south will be strong. One of his princes will become stronger than him, and have dominion. His dominion will be a great dominion."
  },
  "6": {
   "zh": "過些年後，他們必互相連合，南方王的女兒必就了北方王來立約；但這女子幫助之力存立不住，王和他所倚靠之力也不能存立。這女子和引導她來的，並生她的，以及當時扶助她的，都必交與死地。",
   "en": "At the end of years they will join themselves together; and the daughter of the king of the south will come to the king of the north to make an agreement; but she will not retain the strength of her arm. He will also not stand, nor will his arm; but she will be given up, with those who brought her, and he who became the father of her, and he who strengthened her in those times."
  },
  "7": {
   "zh": "但這女子的本家（原文是根）必另生一子（子：原文是枝）繼續王位，他必率領軍隊進入北方王的保障，攻擊他們，而且得勝；",
   "en": "“But out of a shoot from her roots one will stand up in his place, who will come to the army, and will enter into the fortress of the king of the north, and will deal against them, and will prevail."
  },
  "8": {
   "zh": "並將他們的神像和鑄成的偶像，與金銀的寶器掠到埃及去。數年之內，他不去攻擊北方的王。",
   "en": "He will also carry their gods, with their molten images, and with their goodly vessels of silver and of gold, captive into Egypt. He will refrain some years from the king of the north."
  },
  "9": {
   "zh": "北方的王（原文是他）必入南方王的國，卻要仍回本地。",
   "en": "He will come into the realm of the king of the south, but he will return into his own land."
  },
  "10": {
   "zh": "北方王（原文是他）的二子必動干戈，招聚許多軍兵。這軍兵前去，如洪水氾濫，又必再去爭戰，直到南方王的保障。",
   "en": "His sons will wage war, and will assemble a multitude of great forces, which will come on, and overflow, and pass through. They will return and wage war, even to his fortress."
  },
  "11": {
   "zh": "南方王必發烈怒，出來與北方王爭戰，擺列大軍；北方王的軍兵必交付他手。",
   "en": "“The king of the south will be moved with anger, and will come out and fight with him, even with the king of the north. He will send out a great multitude, and the multitude will be given into his hand."
  },
  "12": {
   "zh": "他的眾軍高傲，他的心也必自高；他雖使數萬人仆倒，卻不得常勝。",
   "en": "The multitude will be lifted up, and his heart will be exalted. He will cast down tens of thousands, but he won’t prevail."
  },
  "13": {
   "zh": "北方王必回來擺列大軍，比先前的更多。滿了所定的年數，他必率領大軍，帶極多的軍裝來。",
   "en": "The king of the north will return, and will send out a multitude greater than the former. He will come on at the end of the times, even of years, with a great army and with much substance."
  },
  "14": {
   "zh": "那時，必有許多人起來攻擊南方王，並且你本國的強暴人必興起，要應驗那異象，他們卻要敗亡。",
   "en": "“In those times many will stand up against the king of the south. Also the children of the violent among your people will lift themselves up to establish the vision; but they will fall."
  },
  "15": {
   "zh": "北方王必來築壘攻取堅固城；南方的軍兵必站立不住，就是選擇的精兵（原文是民）也無力站住。",
   "en": "So the king of the north will come and cast up a mound, and take a well-fortified city. The forces of the south won’t stand, neither will his chosen people, neither will there be any strength to stand."
  },
  "16": {
   "zh": "來攻擊他的，必任意而行，無人在北方王（原文是他）面前站立得住。他必站在那榮美之地，用手施行毀滅。",
   "en": "But he who comes against him will do according to his own will, and no one will stand before him. He will stand in the glorious land, and destruction will be in his hand."
  },
  "17": {
   "zh": "他必定意用全國之力而來，立公正的約，照約而行，將自己的女兒給南方王為妻，想要敗壞他（或譯：埃及），這計卻不得成就，與自己毫無益處。",
   "en": "He will set his face to come with the strength of his whole kingdom, and with him equitable conditions. He will perform them. He will give him the daughter of women, to corrupt her; but she will not stand, and won’t be for him."
  },
  "18": {
   "zh": "其後他必轉回奪取了許多海島。但有一大帥，除掉他令人受的羞辱，並且使這羞辱歸他本身。",
   "en": "After this he will turn his face to the islands, and will take many; but a prince will cause the reproach offered by him to cease. Yes, moreover, he will cause his reproach to turn on him."
  },
  "19": {
   "zh": "他就必轉向本地的保障，卻要絆跌仆倒，歸於無有。",
   "en": "Then he will turn his face toward the fortresses of his own land; but he will stumble and fall, and won’t be found."
  },
  "20": {
   "zh": "那時，必有一人興起接續他為王，使橫征暴斂的人通行國中的榮美地。這王不多日就必滅亡，卻不因忿怒，也不因爭戰。",
   "en": "“Then one who will cause a tax collector to pass through the kingdom to maintain its glory will stand up in his place; but within few days he shall be destroyed, not in anger, and not in battle."
  },
  "21": {
   "zh": "必有一個卑鄙的人興起接續為王，人未曾將國的尊榮給他，他卻趁人坦然無備的時候，用諂媚的話得國。",
   "en": "“In his place a contemptible person will stand up, to whom they had not given the honor of the kingdom; but he will come in time of security, and will obtain the kingdom by flatteries."
  },
  "22": {
   "zh": "必有無數的軍兵勢如洪水，在他面前沖沒敗壞；同盟的君也必如此。",
   "en": "The overwhelming forces will be overwhelmed from before him, and will be broken. Yes, also the prince of the covenant."
  },
  "23": {
   "zh": "與那君結盟之後，他必行詭詐，因為他必上來以微小的軍（原文是民）成為強盛。",
   "en": "After the treaty made with him he will work deceitfully; for he will come up, and will become strong, with a small people."
  },
  "24": {
   "zh": "趁人坦然無備的時候，他必來到國中極肥美之地，行他列祖和他列祖之祖所未曾行的，將擄物、掠物，和財寶散給眾人，又要設計攻打保障，然而這都是暫時的。",
   "en": "In time of security he will come even on the fattest places of the province. He will do that which his fathers have not done, nor his fathers’ fathers. He will scatter among them prey, plunder, and substance. Yes, he will devise his plans against the strongholds, even for a time."
  },
  "25": {
   "zh": "他必奮勇向前，率領大軍攻擊南方王；南方王也必以極大極強的軍兵與他爭戰，卻站立不住，因為有人設計謀害南方王。",
   "en": "“He will stir up his power and his courage against the king of the south with a great army; and the king of the south will wage war in battle with an exceedingly great and mighty army; but he won’t stand; for they will devise plans against him."
  },
  "26": {
   "zh": "吃王膳的，必敗壞他；他的軍隊必被沖沒，而且被殺的甚多。",
   "en": "Yes, those who eat of his dainties will destroy him, and his army will be swept away. Many will fall down slain."
  },
  "27": {
   "zh": "至於這二王，他們心懷惡計，同席說謊，計謀卻不成就；因為到了定期，事就了結。",
   "en": "As for both these kings, their hearts will be to do mischief, and they will speak lies at one table; but it won’t prosper, for the end will still be at the appointed time."
  },
  "28": {
   "zh": "北方王（原文是他）必帶許多財寶回往本國，他的心反對聖約，任意而行，回到本地。",
   "en": "Then he will return into his land with great wealth. His heart will be against the holy covenant. He will take action, and return to his own land."
  },
  "29": {
   "zh": "到了定期，他必返回，來到南方。後一次卻不如前一次，",
   "en": "“He will return at the appointed time, and come into the south; but it won’t be in the latter time as it was in the former."
  },
  "30": {
   "zh": "因為基提戰船必來攻擊他，他就喪膽而回，又要惱恨聖約，任意而行；他必回來聯絡背棄聖約的人。",
   "en": "For ships of Kittim will come against him. Therefore he will be grieved, and will return, and have indignation against the holy covenant, and will take action. He will even return, and have regard to those who forsake the holy covenant."
  },
  "31": {
   "zh": "他必興兵，這兵必褻瀆聖地，就是保障，除掉常獻的燔祭，設立那行毀壞可憎的。",
   "en": "“Forces will stand on his part, and they will profane the sanctuary, even the fortress, and will take away the continual burnt offering. Then they will set up the abomination that makes desolate."
  },
  "32": {
   "zh": "作惡違背聖約的人，他必用巧言勾引；惟獨認識神的子民必剛強行事。",
   "en": "He will corrupt those who do wickedly against the covenant by flatteries; but the people who know their God will be strong, and take action."
  },
  "33": {
   "zh": "民間的智慧人必訓誨多人；然而他們多日必倒在刀下，或被火燒，或被擄掠搶奪。",
   "en": "“Those who are wise among the people will instruct many; yet they will fall by the sword and by flame, by captivity and by plunder, many days."
  },
  "34": {
   "zh": "他們仆倒的時候，稍得扶助，卻有許多人用諂媚的話親近他們。",
   "en": "Now when they fall, they will be helped with a little help; but many will join themselves to them with flatteries."
  },
  "35": {
   "zh": "智慧人中有些仆倒的，為要熬煉其餘的人，使他們清淨潔白，直到末了；因為到了定期，事就了結。",
   "en": "Some of those who are wise will fall, to refine them, and to purify, and to make them white, even to the time of the end; because it is yet for the time appointed."
  },
  "36": {
   "zh": "王必任意而行，自高自大，超過所有的神，又用奇異的話攻擊萬神之神。他必行事亨通，直到主的忿怒完畢，因為所定的事必然成就。",
   "en": "“The king will do according to his will. He will exalt himself, and magnify himself above every god, and will speak marvelous things against the God of gods. He will prosper until the indignation is accomplished; for that which is determined will be done."
  },
  "37": {
   "zh": "他必不顧他列祖的神，也不顧婦女所羨慕的神，無論何神他都不顧；因為他必自大，高過一切。",
   "en": "He won’t regard the gods of his fathers, or the desire of women, or regard any god; for he will magnify himself above all."
  },
  "38": {
   "zh": "他倒要敬拜保障的神，用金、銀、寶石和可愛之物敬奉他列祖所不認識的神。",
   "en": "But in his place he will honor the god of fortresses. He will honor a god whom his fathers didn’t know with gold, silver, and with precious stones and pleasant things."
  },
  "39": {
   "zh": "他必靠外邦神的幫助，攻破最堅固的保障。凡承認他的，他必將榮耀加給他們，使他們管轄許多人，又為賄賂分地與他們。",
   "en": "He will deal with the strongest fortresses by the help of a foreign god. He will increase with glory whoever acknowledges him. He will cause them to rule over many, and will divide the land for a price."
  },
  "40": {
   "zh": "到末了，南方王要與他交戰。北方王必用戰車、馬兵，和許多戰船，勢如暴風來攻擊他，也必進入列國，如洪水氾濫。",
   "en": "“At the time of the end the king of the south will contend with him; and the king of the north will come against him like a whirlwind, with chariots, with horsemen, and with many ships. He will enter into the countries, and will overflow and pass through."
  },
  "41": {
   "zh": "又必進入那榮美之地，有許多國就被傾覆，但以東人、摩押人，和一大半亞捫人必脫離他的手。",
   "en": "He will enter also into the glorious land, and many countries will be overthrown; but these will be delivered out of his hand: Edom, Moab, and the chief of the children of Ammon."
  },
  "42": {
   "zh": "他必伸手攻擊列國；埃及地也不得脫離。",
   "en": "He will also stretch out his hand on the countries. The land of Egypt won’t escape."
  },
  "43": {
   "zh": "他必把持埃及的金銀財寶和各樣的寶物。利比亞人和古實人都必跟從他。",
   "en": "But he will have power over the treasures of gold and of silver, and over all the precious things of Egypt. The Libyans and the Ethiopians will be at his steps."
  },
  "44": {
   "zh": "但從東方和北方必有消息擾亂他，他就大發烈怒出去，要將多人殺滅淨盡。",
   "en": "But news out of the east and out of the north will trouble him; and he will go out with great fury to destroy and utterly to sweep away many."
  },
  "45": {
   "zh": "他必在海和榮美的聖山中間設立他如宮殿的帳幕；然而到了他的結局，必無人能幫助他。",
   "en": "He will plant the tents of his palace between the sea and the glorious holy mountain; yet he will come to his end, and no one will help him."
  }
 },
 "12": {
  "1": {
   "zh": "那時，保佑你本國之民的天使長（原文是大君）米迦勒必站起來，並且有大艱難，從有國以來直到此時，沒有這樣的。你本國的民中，凡名錄在冊上的，必得拯救。",
   "en": "“At that time Michael will stand up, the great prince who stands for the children of your people; and there will be a time of trouble, such as never was since there was a nation even to that same time. At that time your people will be delivered, everyone who is found written in the book."
  },
  "2": {
   "zh": "睡在塵埃中的，必有多人復醒。其中有得永生的，有受羞辱永遠被憎惡的。",
   "en": "Many of those who sleep in the dust of the earth will awake, some to everlasting life, and some to shame and everlasting contempt."
  },
  "3": {
   "zh": "智慧人必發光，如同天上的光；那使多人歸義的，必發光如星，直到永永遠遠。",
   "en": "Those who are wise will shine as the brightness of the expanse. Those who turn many to righteousness will shine as the stars forever and ever."
  },
  "4": {
   "zh": "但以理啊，你要隱藏這話，封閉這書，直到末時。必有多人來往奔跑（或譯：切心研究），知識就必增長。」",
   "en": "But you, Daniel, shut up the words, and seal the book, even to the time of the end. Many will run back and forth, and knowledge will be increased.”"
  },
  "5": {
   "zh": "我─但以理觀看，見另有兩個人站立：一個在河這邊，一個在河那邊。",
   "en": "Then I, Daniel, looked, and behold, two others stood, one on the river bank on this side, and the other on the river bank on that side."
  },
  "6": {
   "zh": "有一個問那站在河水以上、穿細麻衣的說：「這奇異的事到幾時才應驗呢？」",
   "en": "One said to the man clothed in linen, who was above the waters of the river, “How long will it be to the end of these wonders?”"
  },
  "7": {
   "zh": "我聽見那站在河水以上、穿細麻衣的，向天舉起左右手，指著活到永遠的主起誓說：「要到一載、二載、半載，打破聖民權力的時候，這一切事就都應驗了。」",
   "en": "I heard the man clothed in linen, who was above the waters of the river, when he held up his right hand and his left hand to heaven, and swore by him who lives forever that it will be for a time, times, and a half; and when they have finished breaking in pieces the power of the holy people, all these things will be finished."
  },
  "8": {
   "zh": "我聽見這話，卻不明白，就說：「我主啊，這些事的結局是怎樣呢？」",
   "en": "I heard, but I didn’t understand. Then I said, “My lord, what will be the outcome of these things?”"
  },
  "9": {
   "zh": "他說：「但以理啊，你只管去；因為這話已經隱藏封閉，直到末時。",
   "en": "He said, “Go your way, Daniel; for the words are shut up and sealed until the time of the end."
  },
  "10": {
   "zh": "必有許多人使自己清淨潔白，且被熬煉；但惡人仍必行惡，一切惡人都不明白，惟獨智慧人能明白。",
   "en": "Many will purify themselves, and make themselves white, and be refined; but the wicked will do wickedly; and none of the wicked will understand; but those who are wise will understand."
  },
  "11": {
   "zh": "從除掉常獻的燔祭，並設立那行毀壞可憎之物的時候，必有一千二百九十日。",
   "en": "“From the time that the continual burnt offering is taken away, and the abomination that makes desolate set up, there will be one thousand two hundred ninety days."
  },
  "12": {
   "zh": "等到一千三百三十五日的，那人便為有福。",
   "en": "Blessed is he who waits, and comes to the one thousand three hundred thirty-five days."
  },
  "13": {
   "zh": "「你且去等候結局，因為你必安歇。到了末期，你必起來，享受你的福分。」",
   "en": "“But go you your way until the end; for you will rest, and will stand in your inheritance at the end of the days.”"
  }
 }
};
